-- ===== src/uikit.lua =====
do
    local module = (function()
-- uikit.lua - The widget kit. Every panel in the script is built from these.
-- Module contract: receives the shared table S. Everything this module needs from
-- earlier modules is pulled into locals below; everything later modules need is
-- assigned onto S at the bottom. Load order is fixed by main.lua / build.py.
return function(S)
local RT = S.RT
local CFG = S.CFG
local LocalPlayer = S.LocalPlayer
local UserInputService = S.UserInputService
local RunService = S.RunService

-- =========================================================================
-- THE KIT
--
-- A faithful port of the Figma kit (file z7K7RSX8F911V8r4Q01nSU). Every number
-- here - colour, radius, gap, font size - comes from that file's variables, so
-- the two stay comparable. Three rules carried over from the design notes:
--
--   * No image assets. Chevrons, the tick, the pencil and the bin are all
--     built from Frames, so there is nothing that can fail to load.
--   * The accent gradient is defined once (Theme.AccentA/Mid/B). Every window,
--     button, toggle and slider fill reads it from here.
--   * Roblox has no box-shadow, so panel elevation is stacked Frames behind
--     the panel at low alpha. Also no asset, and it matches the design's
--     0 14px 34px rgba(0,0,0,.45) closely enough at these sizes.
-- =========================================================================

local Theme = {
    TextPrimary  = Color3.fromHex("f0f0f4"),
    TextSub      = Color3.fromHex("9898a2"),
    TextMuted    = Color3.fromHex("686872"),
    TextOnAccent = Color3.fromHex("1c1606"),
    StatusBad    = Color3.fromHex("ff6060"),
    StatusGood   = Color3.fromHex("5ce08a"),

    SurfaceHeader  = Color3.fromHex("18181c"),
    SurfaceElement = Color3.fromHex("26262c"),
    SurfaceHover   = Color3.fromHex("303038"),
    SurfaceField   = Color3.fromHex("1c1c21"),
    -- A section is a list of settings; its header sits darker than the rows
    -- and its rows sit on a darker well still, so a row (a setting) and a
    -- header (a list you can open) read as two different things.
    SurfaceSection = Color3.fromHex("1e1e24"),
    SurfaceWell    = Color3.fromHex("121216"),
    SurfaceChip    = Color3.fromHex("0c0c0f"),
    Hairline       = Color3.fromHex("323338"),

    -- Window body: a 3-stop vertical fade with per-stop alpha.
    BodyTop = Color3.fromHex("2a2a2f"), BodyMid = Color3.fromHex("1a1a1e"), BodyBot = Color3.fromHex("101013"),
    BodyTopA = 0.05, BodyMidA = 0.13, BodyBotA = 0.42,

    AccentA   = Color3.fromHex("ff841a"),
    AccentMid = Color3.fromHex("ffb626"),
    AccentB   = Color3.fromHex("ffec52"),

    RadiusSm = 5, RadiusMd = 6, RadiusLg = 8,
    GapSm = 6, GapMd = 8, GapLg = 12, GapXl = 14,
    RowH = 34, HeaderH = 40,
}

-- Montserrat and Roboto Mono, per the design. FontFace carries a real weight;
-- the Enum fallback is for any client where the family will not resolve.
local FONT_FAMILY = {
    sans = "rbxasset://fonts/families/Montserrat.json",
    mono = "rbxasset://fonts/families/RobotoMono.json",
}
local FALLBACK = {
    [Enum.FontWeight.Regular] = Enum.Font.Gotham,
    [Enum.FontWeight.Medium] = Enum.Font.GothamMedium,
    [Enum.FontWeight.SemiBold] = Enum.Font.GothamBold,
    [Enum.FontWeight.Bold] = Enum.Font.GothamBold,
}

local function setFont(label, family, weight)
    local ok = pcall(function()
        label.FontFace = Font.new(FONT_FAMILY[family], weight)
    end)
    if not ok then
        label.Font = FALLBACK[weight] or Enum.Font.Gotham
    end
end

-- The named text styles from the Figma file, so a call site says what a piece
-- of text IS rather than restating three properties.
local STYLES = {
    windowTitle = { family = "sans", weight = Enum.FontWeight.SemiBold, size = 15, color = "TextPrimary" },
    windowChip  = { family = "sans", weight = Enum.FontWeight.Bold,     size = 15, color = "TextPrimary" },
    rowLabel    = { family = "sans", weight = Enum.FontWeight.Medium,   size = 13, color = "TextPrimary" },
    rowButton   = { family = "sans", weight = Enum.FontWeight.SemiBold, size = 13, color = "TextOnAccent" },
    rowEntry    = { family = "sans", weight = Enum.FontWeight.SemiBold, size = 13, color = "TextPrimary" },
    rowStat     = { family = "sans", weight = Enum.FontWeight.Medium,   size = 14, color = "TextPrimary" },
    captionKey  = { family = "sans", weight = Enum.FontWeight.Medium,   size = 12, color = "TextSub" },
    captionSub  = { family = "sans", weight = Enum.FontWeight.Regular,  size = 10, color = "TextMuted" },
    captionStat = { family = "sans", weight = Enum.FontWeight.Bold,     size = 12, color = "TextSub" },
    monoValue   = { family = "mono", weight = Enum.FontWeight.Medium,   size = 11, color = "TextOnAccent" },
    monoMeta    = { family = "mono", weight = Enum.FontWeight.Medium,   size = 10, color = "TextMuted" },
    monoStat    = { family = "mono", weight = Enum.FontWeight.Medium,   size = 13, color = "TextSub" },
}

local function corner(instance, radius)
    local c = Instance.new("UICorner")
    c.CornerRadius = UDim.new(0, radius)
    c.Parent = instance
    return c
end

local function stroke(instance, color, thickness)
    local s = Instance.new("UIStroke")
    s.Color = color or Theme.Hairline
    s.Thickness = thickness or 1
    s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    s.Parent = instance
    return s
end

local function pad(instance, top, right, bottom, left)
    local p = Instance.new("UIPadding")
    p.PaddingTop = UDim.new(0, top)
    p.PaddingRight = UDim.new(0, right)
    p.PaddingBottom = UDim.new(0, bottom)
    p.PaddingLeft = UDim.new(0, left)
    p.Parent = instance
    return p
end

local function vlist(instance, gap, order)
    local l = Instance.new("UIListLayout")
    l.FillDirection = Enum.FillDirection.Vertical
    l.Padding = UDim.new(0, gap or Theme.GapSm)
    l.SortOrder = order or Enum.SortOrder.LayoutOrder
    l.Parent = instance
    return l
end

-- Let a child eat the slack in a horizontal list: `reserve` is the width its
-- siblings and the gaps between them take up.
--
-- This used to add a UIFlexItem in Fill mode, and that is what made every row
-- label render blank in 2.7.0. Flex GROWS an item from its base size, and the
-- labels had a base width of 100% - so the pass had negative slack to hand out
-- and collapsed them to nothing. The buttons were fine because their base width
-- was already 0. Explicit arithmetic is one line, needs no guessing about how
-- flex distributes, and cannot fail silently: a wrong `reserve` gives a label
-- that is slightly the wrong width, not an invisible one.
local function flexFill(instance, reserve, heightScale, heightOffset)
    if not reserve then return false end
    -- Height is passed in rather than read back off the instance: every caller
    -- wants full height, and reading Size just to rebuild it was one more thing
    -- to get wrong.
    instance.Size = UDim2.new(1, -reserve, heightScale or 1, heightOffset or 0)
    return true
end

local function hlist(instance, gap)
    local l = Instance.new("UIListLayout")
    l.FillDirection = Enum.FillDirection.Horizontal
    l.VerticalAlignment = Enum.VerticalAlignment.Center
    l.Padding = UDim.new(0, gap or Theme.GapMd)
    l.SortOrder = Enum.SortOrder.LayoutOrder
    l.Parent = instance
    return l
end

local function label(parent, text, style, order)
    local st = STYLES[style] or STYLES.rowLabel
    local l = Instance.new("TextLabel")
    l.BackgroundTransparency = 1
    l.Text = text or ""
    l.TextColor3 = Theme[st.color]
    l.TextSize = st.size
    l.TextXAlignment = Enum.TextXAlignment.Left
    l.TextYAlignment = Enum.TextYAlignment.Center
    l.LayoutOrder = order or 1
    l.Size = UDim2.new(1, 0, 1, 0)
    setFont(l, st.family, st.weight)
    l.Parent = parent
    return l
end

-- The accent gradient, in one place. `rotation` 0 is left-to-right.
local function accentGradient(instance, rotation)
    local g = Instance.new("UIGradient")
    g.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Theme.AccentA),
        ColorSequenceKeypoint.new(0.5, Theme.AccentMid),
        ColorSequenceKeypoint.new(1, Theme.AccentB),
    })
    g.Rotation = rotation or 0
    g.Parent = instance
    return g
end

-- The window body fade: colour and alpha together, as one UIGradient.
local function bodyGradient(instance)
    local g = Instance.new("UIGradient")
    g.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Theme.BodyTop),
        ColorSequenceKeypoint.new(0.45, Theme.BodyMid),
        ColorSequenceKeypoint.new(1, Theme.BodyBot),
    })
    g.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, Theme.BodyTopA),
        NumberSequenceKeypoint.new(0.45, Theme.BodyMidA),
        NumberSequenceKeypoint.new(1, Theme.BodyBotA),
    })
    g.Rotation = 90
    g.Parent = instance
    return g
end

-- Elevation. Roblox has no box-shadow and the kit takes no image assets, so a
-- soft edge is approximated with N frames behind the panel, each a little
-- larger and pushed a little further down, all at low alpha. Eight at 0.07
-- accumulate to about 0.44 in the middle, which is the design's 0.45.
local function shadow(frame, layers, step, drop, alpha, radius)
    layers = layers or 8
    step = step or 2.2
    drop = drop or 14
    alpha = alpha or 0.07
    radius = radius or Theme.RadiusLg
    local holder = Instance.new("Frame")
    holder.Name = "Shadow"
    holder.BackgroundTransparency = 1
    holder.Size = UDim2.fromScale(1, 1)
    holder.ZIndex = frame.ZIndex - 1
    holder.Parent = frame

    for i = 1, layers do
        local spread = i * step
        local offset = drop * (i / layers)
        local layer = Instance.new("Frame")
        layer.Name = "L" .. i
        layer.BackgroundColor3 = Color3.new(0, 0, 0)
        layer.BackgroundTransparency = 1 - alpha
        layer.BorderSizePixel = 0
        layer.ZIndex = frame.ZIndex - 1
        layer.Position = UDim2.fromOffset(-spread, -spread + offset)
        layer.Size = UDim2.new(1, spread * 2, 1, spread * 2)
        corner(layer, radius + spread)
        layer.Parent = holder
    end
    return holder
end

-- =========================================================================
-- Tooltip: one shared box, shown after a second of hovering, following the
-- mouse. Everything with an explanation registers through `tip`.
-- =========================================================================
local Tip = { frame = nil, label = nil, target = nil, showAt = nil, conn = nil }

local function ensureTip(screenGui)
    if Tip.frame and Tip.frame.Parent then return end
    local f = Instance.new("Frame")
    f.Name = "Tooltip"
    f.BackgroundColor3 = Color3.fromHex("3a3a42")
    f.BorderSizePixel = 0
    f.Visible = false
    f.ZIndex = 500
    f.AutomaticSize = Enum.AutomaticSize.XY
    f.Size = UDim2.fromOffset(0, 0)
    f.Parent = screenGui
    corner(f, Theme.RadiusSm)
    stroke(f, Color3.fromHex("4a4a55"), 1)
    pad(f, 6, 8, 6, 8)

    local l = Instance.new("TextLabel")
    l.BackgroundTransparency = 1
    l.AutomaticSize = Enum.AutomaticSize.XY
    l.Size = UDim2.fromOffset(0, 0)
    l.TextWrapped = true
    l.TextXAlignment = Enum.TextXAlignment.Left
    l.TextYAlignment = Enum.TextYAlignment.Top
    l.TextColor3 = Color3.fromHex("e8e8ee")
    l.TextSize = 11
    l.ZIndex = 501
    setFont(l, "sans", Enum.FontWeight.Medium)
    l.Parent = f

    -- AutomaticSize with wrapping needs an upper bound or a long line runs off
    -- the screen; 240px matches the design's tooltip.
    local size = Instance.new("UISizeConstraint")
    size.MaxSize = Vector2.new(240, math.huge)
    size.Parent = l

    Tip.frame, Tip.label = f, l

    -- One clock for every tooltip: the delay, and the follow.
    if Tip.conn then Tip.conn:Disconnect() end
    Tip.conn = RunService.RenderStepped:Connect(function()
        if not Tip.target then return end
        local now = os.clock()
        if not Tip.frame.Visible then
            if now < Tip.showAt then return end
            Tip.frame.Visible = true
        end
        local m = UserInputService:GetMouseLocation()
        local camera = workspace.CurrentCamera
        local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
        local w, h = Tip.frame.AbsoluteSize.X, Tip.frame.AbsoluteSize.Y
        -- Flip to the other side of the cursor near an edge rather than
        -- letting the box hang off screen.
        local x = (m.X + 16 + w > viewport.X) and (m.X - 16 - w) or (m.X + 16)
        local y = (m.Y + 18 + h > viewport.Y) and (m.Y - 12 - h) or (m.Y + 18)
        Tip.frame.Position = UDim2.fromOffset(x, y)
    end)
end

local function hideTip()
    Tip.target = nil
    if Tip.frame then Tip.frame.Visible = false end
end

-- Attaches an explanation to any GuiObject.
local function tip(instance, text)
    if not text or text == "" then return instance end
    instance.MouseEnter:Connect(function()
        if not Tip.frame then return end
        Tip.target = instance
        Tip.showAt = os.clock() + 1.0
        Tip.frame.Visible = false
        Tip.label.Text = text
    end)
    instance.MouseLeave:Connect(function()
        if Tip.target == instance then hideTip() end
    end)
    -- A destroyed widget must not leave its tooltip stranded on screen.
    instance.AncestryChanged:Connect(function()
        if not instance:IsDescendantOf(game) and Tip.target == instance then hideTip() end
    end)
    return instance
end

-- =========================================================================
-- Primitives
-- =========================================================================

-- Chevron: two rounded bars, never a glyph and never an image.
local function chevron(parent)
    local holder = Instance.new("Frame")
    holder.Name = "Chevron"
    holder.BackgroundTransparency = 1
    holder.Size = UDim2.fromOffset(16, 16)
    holder.LayoutOrder = 99
    holder.Parent = parent

    local function bar(name, x, angle)
        local b = Instance.new("Frame")
        b.Name = name
        b.BackgroundColor3 = Theme.TextSub
        b.BorderSizePixel = 0
        b.AnchorPoint = Vector2.new(0.5, 0.5)
        b.Position = UDim2.fromOffset(x, 8)
        b.Size = UDim2.fromOffset(8, 2)
        b.Rotation = angle
        corner(b, 1)
        b.Parent = holder
        return b
    end
    local left = bar("L", 5, 45)
    local right = bar("R", 11, -45)

    -- A table, not fields on the Instance: Roblox objects reject new members.
    return {
        frame = holder,
        setOpen = function(open)
            left.Rotation = open and -45 or 45
            right.Rotation = open and 45 or -45
            local c = open and Theme.AccentMid or Theme.TextSub
            left.BackgroundColor3 = c
            right.BackgroundColor3 = c
        end,
    }
end

-- A control row: the base for everything with a label on the left.
-- `reserve` is how much room the right-hand controls need (their width plus
-- the gap), used only if UIFlexItem is unavailable.
local function row(parent, text, order, height, reserve)
    local r = Instance.new("Frame")
    r.Name = "Row"
    r.BackgroundColor3 = Theme.SurfaceElement
    r.BorderSizePixel = 0
    r.Size = UDim2.new(1, 0, 0, height or Theme.RowH)
    r.LayoutOrder = order or 1
    r.Parent = parent
    corner(r, Theme.RadiusMd)
    stroke(r, Theme.Hairline, 1)
    pad(r, 0, Theme.GapLg, 0, Theme.GapLg)
    local layout = hlist(r, Theme.GapMd)

    local l = label(r, text, "rowLabel", 1)
    l.Size = UDim2.new(1, 0, 1, 0)
    l.TextTruncate = Enum.TextTruncate.AtEnd
    -- The label takes the slack so the control sits hard right.
    flexFill(l, reserve or 24)

    return r, l, layout
end

-- Rows light up under the cursor, and a clickable row reports clicks on ITSELF.
--
-- This used to drop a full-width invisible TextButton into the row to catch the
-- click. That is what made every row label vanish in 2.7.0/2.7.1: a row has a
-- horizontal UIListLayout, the layout lays out ALL GuiObject children, and the
-- hit button was Size (1,1) scale at LayoutOrder 0 - so it sorted first, took
-- the whole width, and pushed the label and the control off the right-hand edge
-- where the window clipped them. Captions, buttons and list entries were fine
-- precisely because none of them go through row().
--
-- A Frame with Active = true raises InputBegan for mouse buttons on its own, so
-- no extra child is needed and nothing joins the layout.
local function hoverable(frame, clickable)
    -- Whatever the frame was painted is what it goes back to: section headers
    -- are darker than ordinary rows and must not come back as one.
    local base = frame.BackgroundColor3
    frame.MouseEnter:Connect(function() frame.BackgroundColor3 = Theme.SurfaceHover end)
    frame.MouseLeave:Connect(function() frame.BackgroundColor3 = base end)
    if not clickable then return nil end
    frame.Active = true
    return {
        onClick = function(fn)
            frame.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch then
                    fn()
                end
            end)
        end,
    }
end

-- Toggle: 38x20, the knob slides and the track takes the accent when on.
local function toggle(parent, text, get, set, order, explain)
    local r, _, _ = row(parent, text, order, nil, 46)
    local hit = hoverable(r, true)

    local track = Instance.new("Frame")
    track.Name = "Track"
    track.BackgroundColor3 = Theme.SurfaceField
    track.BorderSizePixel = 0
    track.Size = UDim2.fromOffset(38, 20)
    track.LayoutOrder = 2
    track.Parent = r
    corner(track, 10)
    local trackStroke = stroke(track, Theme.Hairline, 1)
    local grad = accentGradient(track, 0)
    grad.Enabled = false

    local knob = Instance.new("Frame")
    knob.Name = "Knob"
    knob.BackgroundColor3 = Theme.TextMuted
    knob.BorderSizePixel = 0
    knob.Size = UDim2.fromOffset(14, 14)
    knob.Position = UDim2.fromOffset(2, 3)
    knob.ZIndex = 2
    corner(knob, 7)
    knob.Parent = track

    local function render()
        local on = get() and true or false
        grad.Enabled = on
        track.BackgroundColor3 = on and Color3.new(1, 1, 1) or Theme.SurfaceField
        trackStroke.Transparency = on and 1 or 0
        knob.BackgroundColor3 = on and Theme.TextOnAccent or Theme.TextMuted
        knob.Position = UDim2.fromOffset(on and 22 or 2, 3)
    end
    render()
    hit.onClick(function()
        set(not get())
        render()
    end)
    tip(r, explain)
    return { row = r, render = render }
end

-- Slider: label + description, then an 18px track whose fill carries the
-- readout on its right edge, so the number always sits on the accent.
local function slider(parent, text, desc, minVal, maxVal, isFloat, get, set, order, explain)
    local holder = Instance.new("Frame")
    holder.Name = "Slider"
    holder.BackgroundTransparency = 1
    holder.AutomaticSize = Enum.AutomaticSize.Y
    holder.Size = UDim2.new(1, 0, 0, 0)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    vlist(holder, Theme.GapSm)

    local head = Instance.new("Frame")
    head.Name = "Head"
    head.BackgroundTransparency = 1
    head.AutomaticSize = Enum.AutomaticSize.Y
    head.Size = UDim2.new(1, 0, 0, 0)
    head.LayoutOrder = 1
    head.Parent = holder
    vlist(head, 1)

    local title = label(head, text, "rowLabel", 1)
    title.Size = UDim2.new(1, 0, 0, 18)
    if desc and desc ~= "" then
        local sub = label(head, desc, "captionSub", 2)
        sub.Size = UDim2.new(1, 0, 0, 12)
    end

    local track = Instance.new("Frame")
    track.Name = "Track"
    track.BackgroundColor3 = Theme.SurfaceField
    track.BorderSizePixel = 0
    track.Size = UDim2.new(1, 0, 0, 18)
    track.ClipsDescendants = true
    track.LayoutOrder = 2
    track.Active = true
    track.Parent = holder
    corner(track, Theme.RadiusSm)
    stroke(track, Theme.Hairline, 1)

    local fill = Instance.new("Frame")
    fill.Name = "Fill"
    fill.BackgroundColor3 = Color3.new(1, 1, 1)
    fill.BorderSizePixel = 0
    fill.Size = UDim2.fromScale(0, 1)
    fill.Parent = track
    corner(fill, Theme.RadiusSm)
    accentGradient(fill, 0)

    -- The readout rides the fill's right edge while there is room for it, and
    -- steps outside onto the dark remainder when the fill gets too short.
    local readout = Instance.new("TextLabel")
    readout.Name = "Value"
    readout.BackgroundTransparency = 1
    readout.Size = UDim2.new(1, -8, 1, 0)
    readout.Position = UDim2.fromOffset(0, 0)
    readout.TextXAlignment = Enum.TextXAlignment.Right
    readout.TextColor3 = Theme.TextOnAccent
    readout.TextSize = 11
    readout.ZIndex = 3
    setFont(readout, "mono", Enum.FontWeight.Medium)
    readout.Parent = fill

    local function format(value)
        if isFloat then return string.format("%.1f", value) end
        return tostring(math.floor(value + 0.5))
    end

    local function render()
        local value = get()
        local alpha = math.clamp((value - minVal) / (maxVal - minVal), 0, 1)
        fill.Size = UDim2.fromScale(alpha, 1)
        readout.Text = format(value)
        if alpha < 0.22 then
            -- Outside the fill, in primary, per the design note.
            readout.Parent = track
            readout.Size = UDim2.new(1, -8, 1, 0)
            readout.TextColor3 = Theme.TextPrimary
        else
            readout.Parent = fill
            readout.Size = UDim2.new(1, -8, 1, 0)
            readout.TextColor3 = Theme.TextOnAccent
        end
    end
    render()

    local dragging = false
    local function setFromX(x)
        if track.AbsoluteSize.X <= 0 then return end
        local alpha = math.clamp((x - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
        local value = minVal + (maxVal - minVal) * alpha
        if isFloat then
            value = math.floor(value * 10 + 0.5) / 10
        else
            value = math.floor(value + 0.5)
        end
        set(value)
        render()
    end
    track.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            setFromX(input.Position.X)
        end
    end)
    table.insert(S.sliderConnections, UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch) then
            setFromX(input.Position.X)
        end
    end))
    table.insert(S.sliderConnections, UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end))

    tip(holder, explain)
    return { holder = holder, render = render }
end

-- Dropdown row: the current value, a chevron, and a list that drops under it.
local function dropdown(parent, text, options, get, set, order, explain)
    local holder = Instance.new("Frame")
    holder.Name = "Dropdown"
    holder.BackgroundTransparency = 1
    holder.AutomaticSize = Enum.AutomaticSize.Y
    holder.Size = UDim2.new(1, 0, 0, 0)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    vlist(holder, 4)

    local r, _, _ = row(holder, text, 1, nil, 90)
    local hit = hoverable(r, true)

    local value = label(r, "", "captionKey", 2)
    value.Size = UDim2.fromOffset(0, 18)
    value.AutomaticSize = Enum.AutomaticSize.X
    value.TextXAlignment = Enum.TextXAlignment.Right

    local chev = chevron(r)

    local menu = Instance.new("Frame")
    menu.Name = "Menu"
    menu.BackgroundColor3 = Theme.SurfaceField
    menu.BorderSizePixel = 0
    menu.AutomaticSize = Enum.AutomaticSize.Y
    menu.Size = UDim2.new(1, 0, 0, 0)
    menu.Visible = false
    menu.LayoutOrder = 2
    menu.Parent = holder
    corner(menu, Theme.RadiusMd)
    stroke(menu, Theme.Hairline, 1)
    pad(menu, 4, 4, 4, 4)
    vlist(menu, 2)

    local optionButtons = {}
    local function render()
        local current = get()
        value.Text = tostring(current)
        for optValue, button in pairs(optionButtons) do
            local on = optValue == current
            button.BackgroundColor3 = on and Theme.SurfaceHover or Theme.SurfaceElement
            button.TextColor3 = on and Theme.AccentMid or Theme.TextSub
        end
    end

    for i, option in ipairs(options) do
        local b = Instance.new("TextButton")
        b.Name = tostring(option.value)
        b.BackgroundColor3 = Theme.SurfaceElement
        b.BorderSizePixel = 0
        b.Size = UDim2.new(1, 0, 0, 26)
        b.Text = option.label or tostring(option.value)
        b.TextColor3 = Theme.TextSub
        b.TextSize = 12
        b.LayoutOrder = i
        setFont(b, "sans", Enum.FontWeight.Medium)
        b.Parent = menu
        corner(b, 4)
        b.MouseButton1Click:Connect(function()
            set(option.value)
            menu.Visible = false
            chev.setOpen(false)
            render()
        end)
        optionButtons[option.value] = b
    end
    render()

    hit.onClick(function()
        menu.Visible = not menu.Visible
        chev.setOpen(menu.Visible)
    end)
    -- Clicking an option closes the menu; keep the chevron honest.
    render()
    tip(r, explain)
    return { holder = holder, render = render }
end

-- Swatch + colour picker. The SV square is one frame with two stacked fills -
-- white to hue horizontally, clear to black vertically - exactly as the design
-- describes; changing the hue only touches the first gradient's second stop.
local function colorRow(parent, text, get, set, order, explain)
    local holder = Instance.new("Frame")
    holder.Name = "Color"
    holder.BackgroundTransparency = 1
    holder.AutomaticSize = Enum.AutomaticSize.Y
    holder.Size = UDim2.new(1, 0, 0, 0)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    vlist(holder, Theme.GapSm)

    local r, _, _ = row(holder, text, 1, nil, 54)
    local hit = hoverable(r, true)

    local swatch = Instance.new("Frame")
    swatch.Name = "Swatch"
    swatch.BackgroundColor3 = get()
    swatch.BorderSizePixel = 0
    swatch.Size = UDim2.fromOffset(46, 20)
    swatch.LayoutOrder = 2
    swatch.Parent = r
    corner(swatch, Theme.RadiusSm)
    stroke(swatch, Theme.Hairline, 1)

    local picker = Instance.new("Frame")
    picker.Name = "Picker"
    picker.BackgroundTransparency = 1
    picker.Size = UDim2.new(1, 0, 0, 140)
    picker.Visible = false
    picker.LayoutOrder = 2
    picker.Parent = holder
    hlist(picker, Theme.GapMd)

    local sv = Instance.new("Frame")
    sv.Name = "SV"
    sv.BackgroundColor3 = Color3.new(1, 1, 1)
    sv.BorderSizePixel = 0
    sv.Size = UDim2.new(1, -22, 1, 0)
    sv.Active = true
    sv.LayoutOrder = 1
    sv.Parent = picker
    corner(sv, Theme.RadiusMd)
    flexFill(sv, 22)   -- the hue rail (14) plus the gap (8)

    local hueGradient = Instance.new("UIGradient")
    hueGradient.Rotation = 0
    hueGradient.Parent = sv

    local shade = Instance.new("Frame")
    shade.Name = "Shade"
    shade.BackgroundColor3 = Color3.new(0, 0, 0)
    shade.BorderSizePixel = 0
    shade.Size = UDim2.fromScale(1, 1)
    shade.Parent = sv
    corner(shade, Theme.RadiusMd)
    local shadeGradient = Instance.new("UIGradient")
    shadeGradient.Rotation = 90
    shadeGradient.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1),
        NumberSequenceKeypoint.new(1, 0),
    })
    shadeGradient.Parent = shade

    local cursor = Instance.new("Frame")
    cursor.Name = "Cursor"
    cursor.BackgroundTransparency = 1
    cursor.AnchorPoint = Vector2.new(0.5, 0.5)
    cursor.Size = UDim2.fromOffset(12, 12)
    cursor.ZIndex = 4
    cursor.Parent = sv
    corner(cursor, 6)
    stroke(cursor, Color3.new(1, 1, 1), 2)

    local hue = Instance.new("Frame")
    hue.Name = "Hue"
    hue.BackgroundColor3 = Color3.new(1, 1, 1)
    hue.BorderSizePixel = 0
    hue.Size = UDim2.new(0, 14, 1, 0)
    hue.Active = true
    hue.LayoutOrder = 2
    hue.Parent = picker
    corner(hue, Theme.RadiusSm)
    local rail = Instance.new("UIGradient")
    rail.Rotation = 90
    rail.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 0, 0)),
        ColorSequenceKeypoint.new(0.17, Color3.fromRGB(255, 255, 0)),
        ColorSequenceKeypoint.new(0.33, Color3.fromRGB(0, 255, 0)),
        ColorSequenceKeypoint.new(0.50, Color3.fromRGB(0, 255, 255)),
        ColorSequenceKeypoint.new(0.67, Color3.fromRGB(0, 0, 255)),
        ColorSequenceKeypoint.new(0.83, Color3.fromRGB(255, 0, 255)),
        ColorSequenceKeypoint.new(1.00, Color3.fromRGB(255, 0, 0)),
    })
    rail.Parent = hue

    local marker = Instance.new("Frame")
    marker.Name = "Marker"
    marker.BackgroundColor3 = Color3.new(1, 1, 1)
    marker.BorderSizePixel = 0
    marker.AnchorPoint = Vector2.new(0.5, 0.5)
    marker.Size = UDim2.fromOffset(20, 3)
    marker.Position = UDim2.new(0.5, 0, 0, 0)
    marker.ZIndex = 4
    corner(marker, 2)
    marker.Parent = hue

    local h, s, v = get():ToHSV()

    local function apply()
        local color = Color3.fromHSV(h, s, v)
        swatch.BackgroundColor3 = color
        hueGradient.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromHSV(h, 1, 1))
        cursor.Position = UDim2.fromScale(s, 1 - v)
        marker.Position = UDim2.new(0.5, 0, h, 0)
        set(color)
    end
    apply()

    local draggingSV, draggingHue = false, false
    local function svFromPosition(x, y)
        if sv.AbsoluteSize.X <= 0 then return end
        s = math.clamp((x - sv.AbsolutePosition.X) / sv.AbsoluteSize.X, 0, 1)
        v = 1 - math.clamp((y - sv.AbsolutePosition.Y) / sv.AbsoluteSize.Y, 0, 1)
        apply()
    end
    local function hueFromPosition(y)
        if hue.AbsoluteSize.Y <= 0 then return end
        h = math.clamp((y - hue.AbsolutePosition.Y) / hue.AbsoluteSize.Y, 0, 1)
        apply()
    end

    sv.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            draggingSV = true
            svFromPosition(input.Position.X, input.Position.Y)
        end
    end)
    hue.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            draggingHue = true
            hueFromPosition(input.Position.Y)
        end
    end)
    table.insert(S.sliderConnections, UserInputService.InputChanged:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
        if draggingSV then svFromPosition(input.Position.X, input.Position.Y) end
        if draggingHue then hueFromPosition(input.Position.Y) end
    end))
    table.insert(S.sliderConnections, UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            draggingSV, draggingHue = false, false
        end
    end))

    hit.onClick(function()
        picker.Visible = not picker.Visible
    end)
    tip(r, explain)
    return { holder = holder, render = apply }
end

-- Button. "accent" is the primary action; "ghost" is the in-section default.
local function button(parent, text, style, onClick, order, explain)
    local b = Instance.new("TextButton")
    b.Name = "Button"
    b.BorderSizePixel = 0
    b.Size = UDim2.new(1, 0, 0, 32)
    b.Text = text
    b.TextSize = 13
    b.AutoButtonColor = false
    b.LayoutOrder = order or 1
    setFont(b, "sans", Enum.FontWeight.SemiBold)
    b.Parent = parent
    corner(b, Theme.RadiusMd)

    if style == "accent" then
        b.BackgroundColor3 = Color3.new(1, 1, 1)
        b.TextColor3 = Theme.TextOnAccent
        accentGradient(b, 0)
    elseif style == "danger" then
        b.BackgroundColor3 = Theme.StatusBad
        -- Dark on the red, as the design has it. #ff6060 is light enough that
        -- dark type has more contrast on it than white does.
        b.TextColor3 = Theme.TextOnAccent
    else
        b.BackgroundColor3 = Theme.SurfaceElement
        b.TextColor3 = Theme.TextPrimary
        stroke(b, Theme.Hairline, 1)
        b.MouseEnter:Connect(function() b.BackgroundColor3 = Theme.SurfaceHover end)
        b.MouseLeave:Connect(function() b.BackgroundColor3 = Theme.SurfaceElement end)
    end

    if onClick then b.MouseButton1Click:Connect(onClick) end
    tip(b, explain)
    return b
end

-- A horizontal strip of equal-width buttons.
local function buttonRow(parent, order)
    local holder = Instance.new("Frame")
    holder.Name = "Buttons"
    holder.BackgroundTransparency = 1
    holder.Size = UDim2.new(1, 0, 0, 32)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    hlist(holder, Theme.GapMd)

    local count = 0
    local buttons = {}
    -- Equal widths without UIFlexItem would need to know the final count up
    -- front, so the fallback re-sizes every sibling as each one is added.
    local api = { frame = holder }
    function api.add(text, style, onClick, explain)
        count = count + 1
        local b = button(holder, text, style, onClick, count, explain)
        b.Size = UDim2.new(0, 0, 1, 0)
        buttons[count] = b
        -- Equal widths, recomputed as each button is added.
        for _, sibling in ipairs(buttons) do
            sibling.Size = UDim2.new(1 / count, -(Theme.GapMd * (count - 1)) / count, 1, 0)
        end
        return b
    end
    return api
end

-- =========================================================================
-- Window and section
-- =========================================================================

local function makeDraggable(handle, target)
    local dragging, startPos, startOffset = false, nil, nil
    handle.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            startPos = input.Position
            startOffset = target.Position
        end
    end)
    handle.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)
    table.insert(S.sliderConnections, UserInputService.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local delta = input.Position - startPos
        target.Position = UDim2.new(
            startOffset.X.Scale, startOffset.X.Offset + delta.X,
            startOffset.Y.Scale, startOffset.Y.Offset + delta.Y)
    end))
end

-- A window: accent bar, header (drag handle, accent tile, title, optional ⓘ),
-- hairline divider, then a scrolling body. The body scrolls because a full
-- accordion is taller than a 768p screen, which is the one thing a fixed
-- height would get wrong on half the machines this runs on.
local function window(parent, opts)
    local frame = Instance.new("Frame")
    frame.Name = opts.name or "Window"
    frame.BackgroundColor3 = Color3.new(1, 1, 1)
    frame.BorderSizePixel = 0
    frame.Size = UDim2.fromOffset(opts.width or 310, opts.height or 460)
    frame.Position = opts.position or UDim2.fromOffset(40, 40)
    frame.Visible = opts.visible ~= false
    frame.Active = true
    frame.ClipsDescendants = true
    frame.ZIndex = 2
    frame.Parent = parent
    corner(frame, Theme.RadiusLg)
    stroke(frame, Theme.Hairline, 1)
    bodyGradient(frame)
    shadow(frame)

    -- The header runs from the very top with the frame's own radius, so its
    -- corners coincide with the frame's; a square filler hides its rounded
    -- bottom. (ClipsDescendants clips to the rectangle, not the rounding: a
    -- square header at y=3 showed grey past the corners.)
    local header = Instance.new("Frame")
    header.Name = "Header"
    header.BackgroundColor3 = Theme.SurfaceHeader
    header.BorderSizePixel = 0
    header.Size = UDim2.new(1, 0, 0, Theme.HeaderH + 3)
    header.Position = UDim2.fromOffset(0, 0)
    header.Active = true
    header.ZIndex = 3
    header.Parent = frame
    corner(header, Theme.RadiusLg)
    pad(header, 3, 12, 0, 14)

    local headerFill = Instance.new("Frame")
    headerFill.Name = "HeaderFill"
    headerFill.BackgroundColor3 = Theme.SurfaceHeader
    headerFill.BorderSizePixel = 0
    headerFill.Position = UDim2.fromOffset(0, Theme.HeaderH + 3 - Theme.RadiusLg)
    headerFill.Size = UDim2.new(1, 0, 0, Theme.RadiusLg)
    headerFill.ZIndex = 3
    headerFill.Parent = frame

    -- The accent: a pill along the top, inset so its ends stay inside the
    -- corner curve.
    local accent = Instance.new("Frame")
    accent.Name = "AccentBar"
    accent.BackgroundColor3 = Color3.new(1, 1, 1)
    accent.BorderSizePixel = 0
    accent.Position = UDim2.fromOffset(4, 0)
    accent.Size = UDim2.new(1, -8, 0, 3)
    accent.ZIndex = 4
    accent.Parent = frame
    corner(accent, 2)
    accentGradient(accent, 0)
    hlist(header, Theme.GapLg)
    makeDraggable(header, frame)

    local tile = Instance.new("Frame")
    tile.Name = "Icon"
    tile.BackgroundColor3 = Color3.new(1, 1, 1)
    tile.BorderSizePixel = 0
    tile.Size = UDim2.fromOffset(14, 14)
    tile.LayoutOrder = 1
    tile.ZIndex = 4
    tile.Parent = header
    corner(tile, 4)
    accentGradient(tile, 45)

    local title = label(header, opts.title or "Window", "windowTitle", 2)
    title.ZIndex = 4
    -- tile (14) + gap (12), the pin (20) + gap (12), and the info circle
    -- (20) + gap (12) when there is one.
    flexFill(title, 26 + 32 + (opts.info and 32 or 0))

    -- The pin. A pinned window stays on screen after the interface is closed,
    -- so a readout you want while you play does not cost you the whole GUI.
    -- Grey when it is not pinned, accent when it is.
    local pinned = false
    local pin = Instance.new("TextButton")
    pin.Name = "Pin"
    pin.BackgroundColor3 = Theme.SurfaceElement
    pin.BorderSizePixel = 0
    pin.Size = UDim2.fromOffset(20, 20)
    pin.Text = ""
    pin.AutoButtonColor = false
    pin.LayoutOrder = 3
    pin.ZIndex = 4
    pin.Parent = header
    corner(pin, 6)
    local pinStroke = stroke(pin, Theme.Hairline, 1)

    -- A thumbtack, drawn from two frames: no asset to fail to load.
    local pinHead = Instance.new("Frame")
    pinHead.Name = "Head"
    pinHead.BorderSizePixel = 0
    pinHead.AnchorPoint = Vector2.new(0.5, 0.5)
    pinHead.Position = UDim2.fromOffset(10, 7)
    pinHead.Size = UDim2.fromOffset(11, 4)
    pinHead.ZIndex = 5
    corner(pinHead, 2)
    pinHead.Parent = pin

    local pinStem = Instance.new("Frame")
    pinStem.Name = "Stem"
    pinStem.BorderSizePixel = 0
    pinStem.AnchorPoint = Vector2.new(0.5, 0)
    pinStem.Position = UDim2.fromOffset(10, 9)
    pinStem.Size = UDim2.fromOffset(3, 7)
    pinStem.ZIndex = 5
    corner(pinStem, 1)
    pinStem.Parent = pin

    local function renderPin()
        local color = pinned and Theme.AccentMid or Theme.TextMuted
        pinHead.BackgroundColor3 = color
        pinStem.BackgroundColor3 = color
        pinStroke.Color = pinned and Theme.AccentMid or Theme.Hairline
        pin.BackgroundColor3 = pinned and Theme.SurfaceHover or Theme.SurfaceElement
    end
    renderPin()
    tip(pin, "Pin this window so it stays on screen after you close the interface. You can still drag it. Click again to let it hide with the rest.")

    if opts.info then
        local info = Instance.new("TextLabel")
        info.Name = "Info"
        info.BackgroundColor3 = Theme.SurfaceElement
        info.BorderSizePixel = 0
        info.Size = UDim2.fromOffset(20, 20)
        info.Text = "i"
        info.TextColor3 = Theme.TextSub
        info.TextSize = 12
        info.LayoutOrder = 3
        info.ZIndex = 4
        setFont(info, "sans", Enum.FontWeight.Bold)
        info.Parent = header
        corner(info, 10)
        stroke(info, Theme.Hairline, 1)
        tip(info, opts.info)
    end

    local divider = Instance.new("Frame")
    divider.Name = "Divider"
    divider.BackgroundColor3 = Theme.Hairline
    divider.BorderSizePixel = 0
    divider.Size = UDim2.new(1, 0, 0, 1)
    divider.Position = UDim2.fromOffset(0, 3 + Theme.HeaderH)
    divider.ZIndex = 3
    divider.Parent = frame

    local body = Instance.new("ScrollingFrame")
    body.Name = "Body"
    body.BackgroundTransparency = 1
    body.BorderSizePixel = 0
    body.Position = UDim2.fromOffset(0, 4 + Theme.HeaderH)
    -- Stops one radius above the bottom: a row drawn into the corner showed
    -- past the rounding.
    body.Size = UDim2.new(1, 0, 1, -(4 + Theme.HeaderH + Theme.RadiusLg))
    body.CanvasSize = UDim2.new()
    body.AutomaticCanvasSize = Enum.AutomaticSize.Y
    body.ScrollBarThickness = 4
    body.ScrollBarImageColor3 = Color3.fromHex("50505f")
    body.ZIndex = 3
    body.Parent = frame
    pad(body, 10, Theme.GapLg, Theme.GapXl, Theme.GapLg)
    vlist(body, Theme.GapSm)

    local api = { frame = frame, header = header, body = body, title = title }

    function api.isPinned() return pinned end
    function api.setPinned(value)
        pinned = value and true or false
        renderPin()
        if opts.onPinChanged then opts.onPinChanged(api) end
    end
    pin.MouseButton1Click:Connect(function() api.setPinned(not pinned) end)

    return api
end

-- A collapsible section: the Row is the header, the content sits under it and
-- the whole thing grows with what is inside.
local function section(parent, title, order, explain)
    local holder = Instance.new("Frame")
    holder.Name = "Section"
    holder.BackgroundTransparency = 1
    holder.AutomaticSize = Enum.AutomaticSize.Y
    holder.Size = UDim2.new(1, 0, 0, 0)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    vlist(holder, Theme.GapSm)

    local head, headLabel, _ = row(holder, title, 1, nil, 24)
    head.BackgroundColor3 = Theme.SurfaceSection
    local hit = hoverable(head, true)
    local chev = chevron(head)

    -- The rows of an open section sit in a well a shade darker than the
    -- window, so the settings read as cards inside the list they belong to.
    local content = Instance.new("Frame")
    content.Name = "Content"
    content.BackgroundColor3 = Theme.SurfaceWell
    content.BorderSizePixel = 0
    content.AutomaticSize = Enum.AutomaticSize.Y
    content.Size = UDim2.new(1, 0, 0, 0)
    content.Visible = false
    content.LayoutOrder = 2
    content.Parent = holder
    corner(content, Theme.RadiusMd)
    vlist(content, Theme.GapSm)
    pad(content, 6, 6, 6, 6)

    local open = false
    local function setOpen(value)
        open = value and true or false
        content.Visible = open
        chev.setOpen(open)
        headLabel.TextColor3 = open and Theme.AccentMid or Theme.TextPrimary
    end
    setOpen(false)
    hit.onClick(function() setOpen(not open) end)
    tip(head, explain)

    return { holder = holder, content = content, setOpen = setOpen, isOpen = function() return open end }
end

-- A caption line, for the notes under a group of controls.
local function caption(parent, text, order)
    local l = label(parent, text, "captionSub", order)
    l.AutomaticSize = Enum.AutomaticSize.Y
    l.Size = UDim2.new(1, 0, 0, 0)
    l.TextWrapped = true
    l.TextYAlignment = Enum.TextYAlignment.Top
    return l
end

S.UIKit = {
    Theme = Theme,
    setFont = setFont, corner = corner, stroke = stroke, pad = pad,
    vlist = vlist, hlist = hlist, label = label, caption = caption, flexFill = flexFill,
    accentGradient = accentGradient, bodyGradient = bodyGradient, shadow = shadow,
    ensureTip = ensureTip, tip = tip, hideTip = hideTip,
    chevron = chevron, row = row, hoverable = hoverable,
    toggle = toggle, slider = slider, dropdown = dropdown,
    colorRow = colorRow, button = button, buttonRow = buttonRow,
    window = window, section = section,
    makeDraggable = makeDraggable,
}
end
    end)()
    module(S)
end

-- ===== src/reader.lua =====
do
    local module = (function()
-- reader.lua - everything that can hurt, as boxes with live windows [from, untilAt] on os.clock().
-- Sources: attack Models (hitBox + precast, timing by name), bare projectile parts (swept along their velocity),
-- boss remotes (exact paths on the game clock), the precastHitbox bridge, Bob's wall Model, predicted zones.
-- A box is flat: cx/cz centre, either r (round) or ax/az,ha + bx/bz,hb (oriented), cy/hy height; moving ones carry
-- ox/oz, dx/dz, speed, offset, pathStart, halfW/halfL/halfH. cframe/size stay on it for drawing and the recorder.
return function(S)
local CFG, RT, TIMING, HINTS, ATTACKS, OURS = S.CFG, S.RT, S.TIMING, S.PROJECTILE_HINTS, S.ATTACKS, S.OURS
local Workspace, ReplicatedStorage, Players, LocalPlayer = S.Workspace, S.ReplicatedStorage, S.Players, S.LocalPlayer
local log, logT, isOurs, character, flatDistance = S.log, S.logT, S.isOurs, S.character, S.flatDistance
local lower, huge, sqrt, abs, max, min = string.lower, math.huge, math.sqrt, math.abs, math.max, math.min

local RD = { models = {}, parts = {}, zones = {}, enemies = {}, walls = {}, beams = {}, connections = {}, spawns = {}, spawnSet = {}, watch = {},
    seen = setmetatable({}, { __mode = "k" }), shown = setmetatable({}, { __mode = "k" }),
    fanUntil = -huge, lastSweep = -huge, lastEnemyScan = -huge, lastShow = -huge, count = 0 }
local NOT_SPAWNS = { Map = true, dungeon = true, enemies = true, Terrain = true, Lobby = true, Camera = true }

local function gameClock()
    local ts = RD.timeSync
    if ts then local ok, t = pcall(ts.GetTime, ts) if ok and type(t) == "number" then return t end end
    return Workspace:GetServerTimeNow()
end
local function fromGame(t) return os.clock() + (t - gameClock()) end

-- Flat footprint of a part: whichever local axis points up is the height, the other two span the floor.
-- A Part cylinder lies along its X axis with its round face across Y/Z; a round zone is size.X across, size.Y tall.
local function footprint(b, cf, size, round, cyl)
    local p = cf.Position
    b.cx, b.cz, b.cy = p.X, p.Z, p.Y
    if cyl then b.r, b.hy = size.Y * 0.5, size.X * 0.5
    elseif round then b.r, b.hy = size.X * 0.5, size.Y * 0.5
    else
        b.r = nil
        local R, U, L = cf.RightVector, cf.UpVector, cf.LookVector
        local ux, uy, uz = abs(R.Y), abs(U.Y), abs(L.Y)
        local A, B
        if uy >= ux and uy >= uz then A, B, b.ha, b.hb, b.hy = R, L, size.X * 0.5, size.Z * 0.5, size.Y * 0.5
        elseif ux >= uz then A, B, b.ha, b.hb, b.hy = U, L, size.Y * 0.5, size.Z * 0.5, size.X * 0.5
        else A, B, b.ha, b.hb, b.hy = R, U, size.X * 0.5, size.Y * 0.5, size.Z * 0.5 end
        local al, bl = max(sqrt(A.X * A.X + A.Z * A.Z), 1e-3), max(sqrt(B.X * B.X + B.Z * B.Z), 1e-3)
        b.ax, b.az, b.bx, b.bz = A.X / al, A.Z / al, B.X / bl, B.Z / bl
    end
    b.cframe, b.size, b.round, b.cyl, b.moving = cf, size, round, cyl, false
    return b
end

local function addZone(z)
    if not z.moving then footprint(z, z.cframe, z.size, z.round, z.cyl) end
    RD.zones[#RD.zones + 1] = z
    if #RD.zones > 96 then table.remove(RD.zones, 1) end
end
-- Predictions carry madeAt; the game's own zones do not and are never pruned here.
local function dropZones(prefix, olderThan)
    for i = #RD.zones, 1, -1 do
        local z = RD.zones[i]
        if z.madeAt and z.madeAt < olderThan and z.name:sub(1, #prefix) == prefix then table.remove(RD.zones, i) end
    end
end

-- The Champion's passive beams: a slow sweep (20 deg on every 0.5 s, so each chain's next two lanes are zones) or the
-- fast fan (4+ within 0.5 s: RD.fanUntil and a reflex out to fanRadius, where the lanes are far enough apart).
local function wrap180(a) a = a % 180 if a > 90 then a = a - 180 end return a end
local function noteBeam(hb, now)
    local look, beams = hb.CFrame.LookVector, RD.beams
    beams[#beams + 1] = { t = now, yaw = math.deg(math.atan2(look.X, look.Z)) % 180, hub = hb.Position, size = hb.Size }
    if #beams > 24 then table.remove(beams, 1) end
    local recent = 0
    for i = #beams, 1, -1 do if now - beams[i].t <= 0.5 then recent = recent + 1 else break end end
    if recent >= 4 then
        RD.fanUntil = now + 1.5
        local _, _, rt = character()
        if (rt and flatDistance(rt.Position, hb.Position) or 0) < CFG.fanRadius - 4 then
            RT.reflex = { name = "fan", from = hb.Position, radius = CFG.fanRadius, untilAt = now + 3.5 }   -- out to the fan radius as fast as the legs allow
        end
    end
    dropZones("beam next", now - 0.5)
    local b, chains = beams[#beams], 0
    for i = #beams - 1, 1, -1 do
        local a = beams[i]
        local dt, step = b.t - a.t, wrap180(b.yaw - a.yaw)
        if dt > 0.8 then break end
        if dt >= 0.08 and abs(step) >= 15 and abs(step) <= 25 then
            chains = chains + 1
            for k = 1, 2 do
                local yaw, at = math.rad(b.yaw + step * k), now + dt * k
                addZone({ name = "beam next", cframe = CFrame.lookAt(b.hub, b.hub + Vector3.new(math.sin(yaw), 0, math.cos(yaw))), size = b.size, from = at + 0.5, untilAt = at + 1.25, exact = true, madeAt = now })   -- the predicted beam hits 0.77-1.10 s after it appears; a death came 0.3 s before the old 0.6
            end
            if chains >= 2 then break end
        end
    end
end

-- A mage volley marches from the mage through the player, a shot every 0.1 s: two aligned shots reveal the line and
-- the whole line becomes a zone, so the way out is sideways.
local function noteVolley(hb, now)
    local prev, pos = RD.lastShot, hb.Position
    RD.lastShot = { t = now, pos = pos }
    if not prev or now - prev.t > 0.4 then return end
    local flat = Vector3.new(pos.X - prev.pos.X, 0, pos.Z - prev.pos.Z)
    if flat.Magnitude < 6 or flat.Magnitude > 40 then return end
    dropZones("volley next", now - 0.3)
    local centre = pos + flat.Unit * 120
    addZone({ name = "volley next", cframe = CFrame.lookAt(centre, centre + flat.Unit), size = Vector3.new(hb.Size.X, max(hb.Size.Y, 12), 240), from = now + 0.3, untilAt = now + 3.0, telegraphed = true, madeAt = now })
end

-- Bob's circles march along the line through him: one every 0.27 s, 22 studs on, 6 wider, lethal ~0.6 s after each
-- appears. The first circle fixes the line (a soft band: never a spot, but crossable) and predicts nine circles both
-- ways; the second circle gives the direction and the wrong half is dropped.
local function noteCircle(pc, now)
    local pos, size, prev = pc.Position, max(pc.Size.Y, pc.Size.Z), RD.lastCircle
    RD.lastCircle = { t = now, pos = pos, size = size }
    local dir, spacing, growth, dt
    if prev and now - prev.t < 0.6 then
        local step = Vector3.new(pos.X - prev.pos.X, 0, pos.Z - prev.pos.Z)
        if step.Magnitude >= 8 and step.Magnitude <= 45 then dir, spacing, growth, dt = step.Unit, step.Magnitude, size - prev.size, max(now - prev.t, 0.15) end
    end
    if not dir then
        for _, e in ipairs(RD.enemies) do
            if e.isBoss then
                local out = Vector3.new(pos.X - e.x, 0, pos.Z - e.z)
                if out.Magnitude >= 5 then dir = out.Unit end
                break
            end
        end
    end
    if not dir then return end
    dropZones("circle ", now - 0.2)
    local width = spacing and growth > 0 and (size + growth * 3 + 6) or (size + 6)
    -- three nested bands, warmer toward the axis: a spot deeper in the strip costs more, so the field walks out
    -- sideways instead of dithering along the line (two deaths 20+ studs inside the strip, running along it)
    for _, band in ipairs({ { 1.0, 0.5 }, { 0.6, 0.65 }, { 0.3, 0.8 } }) do
        addZone({ name = "circle line", cframe = CFrame.lookAt(pos, pos + dir), size = Vector3.new(width * band[1], 12, 400), from = now, untilAt = now + 3.0, telegraphed = true, madeAt = now, weight = band[2] })
    end
    local function chain(d, sp, gr, step)
        for k = 1, 9 do
            local c, diam, at = pos + d * (sp * k), size + gr * k + 6, now + step * k + 0.1   -- late in the chain a circle kills as it appears (a death 0.6 s before the old prediction opened)
            if diam < 16 then break end
            addZone({ name = "circle next", cframe = CFrame.new(c.X, pos.Y, c.Z), size = Vector3.new(diam, 12, diam), round = true, from = at, untilAt = at + 1.0, telegraphed = true, madeAt = now })
        end
    end
    if spacing then chain(dir, spacing, growth, dt) else chain(dir, 22, 6, 0.27) chain(-dir, 22, -6, 0.27) end
end

local function findPart(model, key)
    for _, d in ipairs(model:GetChildren()) do
        if d:IsA("BasePart") and lower(d.Name):find(key, 1, true) then return d end
    end
end
local function largestPart(model)
    local best, bestA = nil, 0
    for _, d in ipairs(model:GetDescendants()) do
        if d:IsA("BasePart") and d.Size.X * d.Size.Z > bestA then best, bestA = d, d.Size.X * d.Size.Z end
    end
    return best
end
local function ownedByPlayer(inst)
    for _ = 1, 4 do
        inst = inst.Parent
        if not inst then return false end
        if inst:IsA("Model") and Players:GetPlayerFromCharacter(inst) then return true end
    end
    return false
end

local watchReuse   -- defined after trackModel (it calls it)
local function trackModel(model)
    if RD.models[model] or isOurs(model) or ownedByPlayer(model) or model:FindFirstChildOfClass("Humanoid") then return end
    local name, now = lower(model.Name), os.clock()
    if OURS[name] then return end   -- a player ability's visual
    local hb, pc = findPart(model, "hitbox"), findPart(model, "precast")
    -- A Model whose window has run out is done: the Champion parks a pool of passive beam Models at the arena
    -- centre for the whole fight, and re-tracking them from the sweep made the hub fire every four seconds. It
    -- counts again only if it has moved or its precast has come back on.
    local s = RD.seen[model]
    if s and (not hb or (hb.Position - s.pos).Magnitude < 5) and not (pc and pc.Transparency < 0.9 and s.pcT >= 0.9) then return end
    local noTele = false
    if not hb and not pc then   -- a catalogued attack with no telegraph: its biggest part hurts from the moment it exists until it goes
        if not ATTACKS[name] or model.Parent ~= Workspace then return end
        hb, noTele = largestPart(model), true
        if not hb then return end
    end
    local seed = TIMING[name] or {}
    local first = seed.first or ((pc and not noTele) and CFG.defaultFire or 0)
    local long = seed.long == true or (noTele and not seed.last)
    -- Learned timing: the server tests a hitBox with a touch query at the moment of damage, which puts a
    -- TouchTransmitter on the part for one frame. Three such samples for a name and its window is the measured
    -- spread (first hit - 0.1 .. last hit + 0.15), whatever the seed said.
    local learned = RD.hitDelay and RD.hitDelay[name]
    if learned and learned.n >= 3 then
        first = math.max(learned.min - 0.3, 0)   -- a margin for acceleration: at -0.1 the bot left a beam 3 studs late
        long = false
    end
    local rec = { model = model, hb = hb, pc = pc, name = name, spawn = now, from = now + first, untilAt = long and huge or now + (seed.last or first + CFG.defaultLive),
        long = long, noTele = noTele, holdFull = seed.holdFull == true, pad = seed.pad or 0, slim = seed.slim, minT = pc and pc.Transparency or 1 }
    if learned and learned.n >= 3 then rec.untilAt = now + learned.max + 0.15 rec.holdFull = true rec.exact = true end
    rec.exact = rec.exact or seed.exact == true
    RD.models[model] = rec
    RD.count = RD.count + 1
    if hb then
        rec.touchConn = hb.ChildAdded:Connect(function(c)
            if not c:IsA("TouchTransmitter") then return end
            local dt = os.clock() - rec.spawn
            if dt < 0.3 then return end   -- a Model the sweep caught late, not an early hit (a mage shot read 0.05 s once)
            RD.hitDelay = RD.hitDelay or {}
            local h = RD.hitDelay[name] or { n = 0, min = huge, max = 0, sum = 0, list = {} }
            h.n, h.sum = h.n + 1, h.sum + dt
            h.list[#h.list + 1] = dt
            if #h.list > 40 then table.remove(h.list, 1) end
            local sorted = table.clone(h.list)
            table.sort(sorted)
            -- the window is the 10th to 90th percentile of the last forty, so one odd sample cannot stretch it
            h.min, h.max = sorted[math.max(1, math.floor(#sorted * 0.1 + 0.5))], sorted[math.min(#sorted, math.ceil(#sorted * 0.9))]
            RD.hitDelay[name] = h
            rec.hitAt = dt
            -- this Model has hit: it is over once its precast has gone (one more frame of grace)
            if not rec.holdFull or (learned and learned.n >= 3) then rec.untilAt = math.min(rec.untilAt, os.clock() + 0.15) end
        end)
    end
    if hb and name:find("passivebeam", 1, true) then noteBeam(hb, now) end
    if hb and name == "firstbossjumpslam" then RT.reflex = { name = "slam", from = hb.Position, radius = 56, untilAt = now + 2.6, startedAt = now } end   -- appears ~2 s before the hit; the box is a 67 cube, 54 to a corner
    if hb and name:find("mageshot", 1, true) then noteVolley(hb, now) end
    if pc and name:find("cricle", 1, true) then noteCircle(pc, now) end
    if watchReuse and (hb or pc) and not noTele then watchReuse(model, hb, pc) end
end
-- A parked Model cast again: the Champion re-aims a pool of passive beam Models for the whole fight, and a re-aim
-- never moves a full-line hitBox (its centre is the hub), so the sweep's gate (moved, or precast seen off and on)
-- left a Model re-cast within a second of its last hit blind for the rest of the fight - the fan deaths with no
-- beam box anywhere near. The telegraph lighting again (transparency dropping) or a parked hitBox turning re-tracks
-- the Model that frame, whatever the sweep thinks.
local function retrack(model)
    local r = RD.models[model]
    if r then
        if os.clock() - r.spawn < 0.5 then return end   -- a fresh Model settling into place, not a reuse
        if r.touchConn then r.touchConn:Disconnect() end
        RD.models[model] = nil
    end
    RD.seen[model] = nil
    if model.Parent then trackModel(model) end
end
watchReuse = function(model, hb, pc)
    if RD.watch[model] then return end
    local w = { conns = {} }
    RD.watch[model] = w
    if pc then
        local last = pc.Transparency
        w.conns[#w.conns + 1] = pc:GetPropertyChangedSignal("Transparency"):Connect(function()
            local t = pc.Transparency
            if t < last - 0.25 then retrack(model) end   -- lit again: a new cast
            last = t
        end)
    end
    if hb then
        local lastCF = hb.CFrame
        w.conns[#w.conns + 1] = hb:GetPropertyChangedSignal("CFrame"):Connect(function()
            local cf = hb.CFrame
            if not RD.models[model] and ((cf.Position - lastCF.Position).Magnitude > 1 or cf.LookVector:Dot(lastCF.LookVector) < 0.998) then retrack(model) end   -- a parked Model re-aimed (a live one moving is a projectile, left alone)
            lastCF = cf
        end)
    end
    w.conns[#w.conns + 1] = model.AncestryChanged:Connect(function()
        if model.Parent then return end
        for _, c in ipairs(w.conns) do pcall(c.Disconnect, c) end
        RD.watch[model] = nil
        RD.seen[model] = nil
    end)
end
local function trackPart(part)
    if RD.parts[part] or isOurs(part) or ownedByPlayer(part) then return end
    local m = part:FindFirstAncestorOfClass("Model")
    if m and RD.models[m] then return end
    local n = lower(part.Name)
    if OURS[n] then return end
    local reg = ATTACKS[n] == true   -- catalogued by name: a hazard while it exists and is visible, still or not
    if not reg then
        local hit = false
        for _, hint in ipairs(HINTS) do if n:find(hint, 1, true) then hit = true break end end
        if not hit then return end
    end
    local p = part.Position
    RD.parts[part] = { part = part, x = p.X, z = p.Z, vx = 0, vz = 0, at = os.clock(), spawn = os.clock(), reg = reg }
end

-- Our own abilities, per slot: each cast is queued (brain) with where the character and target stood; the projectile
-- that appears within 0.8 s takes the oldest. Landed on the target = reach (at least this far); short of a further
-- target along the aim = the cap. The least ranged slot sets the fight distance.
local function noteOurProjectile(model)
    task.defer(function()
        local q = RT.castQueue
        if not q or #q == 0 then return end
        local cast = table.remove(q, 1)
        local part = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
        if os.clock() - cast.at > 0.8 or not part then return end
        local g = part.Position
        local d, toTarget, targetD = flatDistance(g, cast.pos), flatDistance(g, cast.targetPos), flatDistance(cast.targetPos, cast.pos)
        RD.abilitySlots = RD.abilitySlots or {}
        local slot = RD.abilitySlots[cast.slot] or {}
        RD.abilitySlots[cast.slot] = slot
        slot.name = model.Name
        local area = findPart(model, "hitbox") or largestPart(model)   -- the AoE: the damage part's footprint, whatever its shape
        if area then
            local s = area.Size
            local cyl = area:IsA("Part") and (area.Shape == Enum.PartType.Cylinder or area.Shape == Enum.PartType.Ball)
            slot.aoeX, slot.aoeZ = cyl and max(s.Y, s.Z) or s.X, cyl and max(s.Y, s.Z) or s.Z
            slot.aoeRound = cyl or abs(slot.aoeX - slot.aoeZ) < 1
        end
        if toTarget <= 8 then
            if d > (slot.reach or 0) then slot.reach = math.floor(d + 0.5) end
        elseif targetD > d + 3 then
            local cap = math.floor(d + 0.5)
            if cap >= 15 and cap <= 90 and cap > (slot.cap or 0) then slot.cap = cap end
        end
        if slot.cap and slot.reach and slot.reach > slot.cap + 2 then slot.cap = nil end
        local least, aoe, shape
        for _, s in pairs(RD.abilitySlots) do
            local range = s.cap or s.reach
            if range and (not least or range < least) then least = range end
            if s.aoeX and (not aoe or max(s.aoeX, s.aoeZ) * 0.5 < aoe) then aoe, shape = max(s.aoeX, s.aoeZ) * 0.5, s end   -- the smallest AoE: every slot must cover the group
        end
        RD.abilityRange, RD.abilityReach, RD.aoe, RD.aoeShape = least, least, aoe, shape
        if least and least > (CFG.abilityRangeKnown or 0) then CFG.abilityRangeKnown = least end   -- remembered across runs (config)
    end)
end

-- Something new in the world that nothing recognised: kept ten seconds so the drawing can label it and the name
-- can be added to the catalogue. Not the map, the dungeon, characters, our visuals, or parts of a thing already noted.
local NOT_ATTACKS = { "deatheffect", "particle", "smoke", "neonball", "sound", "effect", "debris", "highlight" }
local function noteSpawn(inst)
    if isOurs(inst) or ownedByPlayer(inst) or OURS[lower(inst.Name)] or inst:FindFirstChildOfClass("Humanoid") then return end
    local ln = lower(inst.Name)
    for _, k in ipairs(NOT_ATTACKS) do if ln:find(k, 1, true) then return end end   -- effects, not attacks (Chris: no death-effect or particle labels)
    local top = inst
    while top.Parent and top.Parent ~= Workspace do
        top = top.Parent
        if RD.spawnSet[top] or RD.models[top] then return end
    end
    if NOT_SPAWNS[top.Name] then return end
    RD.spawnSet[inst] = true
    RD.spawns[#RD.spawns + 1] = { inst = inst, at = os.clock() }
    if #RD.spawns > 80 then RD.spawnSet[table.remove(RD.spawns, 1).inst] = nil end
end
local function consider(inst, fresh)
    local tracked = false
    if inst:IsA("Model") then
        if RT.castQueue and #RT.castQueue > 0 and (RD.ourAbilityNames or {})[inst.Name] then return noteOurProjectile(inst) end
        if lower(inst.Name):find("movingbeam", 1, true) then RD.walls[inst] = RD.walls[inst] or { model = inst, at = os.clock(), born = os.clock(), vx = 0, vz = 0 } return end
        trackModel(inst)
        tracked = RD.models[inst] ~= nil
    elseif inst:IsA("BasePart") then
        if inst.Parent == Workspace then   -- attacks are parented straight to workspace; the streamed map is not (its "rock" parts are not attacks)
            trackPart(inst)
            tracked = RD.parts[inst] ~= nil
        else
            local n = lower(inst.Name)
            local model = (n:find("hitbox", 1, true) or n:find("precast", 1, true)) and inst:FindFirstAncestorOfClass("Model")
            if model then trackModel(model) tracked = RD.models[model] ~= nil end
        end
    else return end
    if fresh and not tracked then noteSpawn(inst) end
end

-- Boss remotes: a body rolling along a line (origin, direction, distance over duration on the game clock), boxed at the
-- moment the field asks for. Announced paths are ground attacks whatever height their CFrame carries.
local function addPath(name, cf, distance, duration, t0, t1, halfW, halfL, halfH, offset)
    local look = cf.LookVector
    local flat = Vector3.new(look.X, 0, look.Z)
    flat = flat.Magnitude < 0.01 and Vector3.new(0, 0, -1) or flat.Unit
    addZone({ name = name, moving = true, ground = true, ox = cf.Position.X, oy = cf.Position.Y, oz = cf.Position.Z, dx = flat.X, dz = flat.Z,
        speed = distance / max(duration, 0.01), offset = offset or 0, halfW = halfW, halfL = halfL, halfH = max(halfH, 6),
        from = fromGame(t0), untilAt = fromGame(t1), pathStart = fromGame(t0) })
end
local function circleZone(name, position, radius, fireGame, holdFor)
    local at = fromGame(fireGame)
    -- the lead grows with the radius: the far edge of a 46-stud zone is two seconds away at escape speed
    addZone({ name = name, cframe = CFrame.new(position), size = Vector3.new(radius * 2, 12, radius * 2), round = true, from = at, untilAt = at + holdFor, telegraphed = true, lead = math.max(CFG.dodgeLead, radius / 20 + 0.5) })
end
local SPIKE_RADIUS = { small = 21, medium = 31, large = 46 }   -- +6: the spikes slowed the character from 2.3 studs outside the Model
local function path5(name, a, w, l, h, offset) if type(a) == "table" and #a >= 5 then addPath(name, a[5], a[1], a[2], a[3], a[4], w, l, h, offset) end end
local HANDLERS = {
    ["First Boss Jump Down"] = function(a)   -- arrives with the hit; the Model's appearance started the reflex already
        if typeof(a) == "Vector3" then
            circleZone("slam soon", a, 38, gameClock() + 2.5, 1.5)
            -- the Model's appearance started the reflex two seconds ago; a fresh one here would hop again
            if not (RT.reflex and RT.reflex.name == "slam") then RT.reflex = { name = "slam", from = a, radius = 56, untilAt = os.clock() + 3.2, hopped = true } end
        end
    end,
    ["First Boss Criss Cross Projectile"] = function(a) path5("criss cross", a, 7.5, 7.5, 8) end,
    ["First Boss Seeking Spike"] = function(a) path5("seeking spike", a, 14, 14, 4) end,   -- it turns toward the player and slows on touch; wider than its mesh
    ["First Boss Big Spike"] = function(a) path5("big spike", a, 28, 28, 6) end,   -- 40 wide, kills 4-7 studs outside its mesh
    ["Second Boss Big Hitting Ground Spikes"] = function(a)
        if type(a) == "table" and typeof(a[2]) == "CFrame" then circleZone("ground spikes", a[2].Position, SPIKE_RADIUS[a[1]] or 31, a[3], 1.2) end   -- the spikes stand ~0.7 s and slow on touch
    end,
    ["Third Boss Bouncing Orb Beam"] = function(a) if typeof(a) == "CFrame" then circleZone("orb beam", a.Position, 12, gameClock(), 6) end end,
    ["Third Boss Sideways Missile"] = function(a) path5("sideways missile", a, 5, 15, 6, -10) end,
    -- Spearman Strike / Warrior Line Strike: their hitbox Models carry the true shape; the 100-stud zone once placed
    -- from the announcement reached far past the strike and is gone.
}

local function scanEnemies(now)
    local list, me = {}, LocalPlayer.Character
    RD.enemyPrev = RD.enemyPrev or setmetatable({}, { __mode = "k" })
    local function visit(folder)
        for _, m in ipairs(folder:GetChildren()) do
            if m:IsA("Model") and m ~= me then
                local hum, root = m:FindFirstChildOfClass("Humanoid"), m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart
                if hum and root and hum.Health > 0 and not Players:GetPlayerFromCharacter(m) then
                    local style, melee, prev, p = m:FindFirstChild("enemyStyle"), m:FindFirstChild("meleeDistance"), RD.enemyPrev[m], root.Position
                    local vx, vz = 0, 0
                    if prev and now > prev.at then vx, vz = (p.X - prev.x) / (now - prev.at), (p.Z - prev.z) / (now - prev.at) end
                    local md = melee and type(melee.Value) == "number" and melee.Value or 4
                    list[#list + 1] = { model = m, root = root, humanoid = hum, x = p.X, y = p.Y, z = p.Z, vx = vx, vz = vz,
                        isBoss = style ~= nil and type(style.Value) == "string" and lower(style.Value):find("boss", 1, true) ~= nil,
                        melee = md <= CFG.meleeMobMaxReach, meleeDistance = md, extent = max(root.Size.X, root.Size.Z) * 0.5 }
                    RD.enemyPrev[m] = { x = p.X, z = p.Z, at = now }
                end
            elseif m:IsA("Folder") or (m:IsA("Model") and m.Name:find("room", 1, true)) then visit(m) end
        end
    end
    for _, name in ipairs({ "dungeon", "enemies" }) do
        local f = Workspace:FindFirstChild(name)
        if f then visit(f) end
    end
    RD.enemies = list
    -- The Champion's arena kills past ~128 studs from him. The leash arms once the character has been inside
    -- (within 110) and stays armed for that boss, so the walk in from room 2 never sees it as a wall.
    RD.leash = nil
    local _, _, rt = character()
    for _, e in ipairs(list) do
        if e.isBoss and e.model.Name == "Midgardian Champion" then
            if RD.leashBoss ~= e.model then RD.leashBoss, RD.leashArmed = e.model, _G.DungeonAutofarmLeashArmed == e.model end
            if rt and not RD.leashArmed and flatDistance(rt.Position, e.root.Position) < 110 then RD.leashArmed = true _G.DungeonAutofarmLeashArmed = e.model end
            if RD.leashArmed then RD.leash = { enemy = e, radius = CFG.leashRadius } end
            break
        end
    end
end

local function readerTick(now)
    if now - (RD.abilityNamesAt or -huge) > 5 then
        RD.abilityNamesAt = now
        local names = {}
        for _, c in ipairs({ LocalPlayer.Backpack, LocalPlayer.Character }) do
            if c then for _, t in ipairs(c:GetChildren()) do if t:IsA("Tool") and t:FindFirstChild("abilitySlot") then names[t.Name] = t.abilitySlot.Value end end end
        end
        RD.ourAbilityNames = names
        if not RD.abilitySlots and (CFG.abilityRangeKnown or 0) > 0 then   -- start from the range the last runs found, not from scratch
            RD.abilitySlots = {}
            for _, slot in pairs(names) do RD.abilitySlots[slot] = { reach = CFG.abilityRangeKnown } end
            RD.abilityRange, RD.abilityReach = CFG.abilityRangeKnown, CFG.abilityRangeKnown
        end
    end
    if now - RD.lastSweep > 0.25 then   -- DescendantAdded misses what is renamed or moved in afterwards
        RD.lastSweep = now
        for _, c in ipairs(Workspace:GetChildren()) do if c:IsA("Model") or c:IsA("BasePart") then consider(c) end end
    end
    if now - RD.lastShow > 1 then   -- the game's own hitBox parts made visible (every attack Model in workspace, tracked or parked), restored when off
        RD.lastShow = now
        if CFG.showHitboxes then
            for _, c in ipairs(Workspace:GetChildren()) do
                local hb = c:IsA("Model") and not OURS[lower(c.Name)] and findPart(c, "hitbox")
                if hb and not RD.shown[hb] and hb.Transparency >= 0.99 then RD.shown[hb], hb.Transparency, hb.Color = true, 0.75, Color3.fromRGB(255, 80, 200) end
            end
        elseif next(RD.shown) then
            for hb in pairs(RD.shown) do pcall(function() hb.Transparency = 1 end) end
            table.clear(RD.shown)
        end
    end
    for model, r in pairs(RD.models) do
        local gone = not model.Parent or (r.hb and not r.hb.Parent and r.pc and not r.pc.Parent)
        local done = (gone and (r.long or now > r.untilAt or not r.box)) or now > r.untilAt + 0.5
            or (r.noTele and now - r.spawn > 0.5 and r.hb.Transparency >= CFG.spentTransparency)   -- faded out in place
        if done then
            if r.touchConn then r.touchConn:Disconnect() end
            RD.models[model] = nil
            if not gone then RD.seen[model] = { pos = r.hb and r.hb.Position or Vector3.zero, pcT = r.pc and r.pc.Transparency or 1 } end
        elseif r.pc and r.pc.Parent then   -- precast fade = fired; fade + linger = over, unless the seed says it burns on
            local tr = r.pc.Transparency
            if tr < r.minT then r.minT = tr end
            if not r.fired and r.minT < 0.9 and tr > r.minT + 0.08 and tr >= 0.9 then
                r.fired = true
                if now < r.from then r.from = now end
                if not r.long and not r.holdFull then r.untilAt = min(r.untilAt, max(now + CFG.fadeLinger, r.from + 0.2)) end
            end
        end
    end
    for model, w in pairs(RD.walls) do   -- Bob's wall: centre from its two balls, velocity from position (~19 studs/s)
        local b1, b2 = model:FindFirstChild("ball1"), model:FindFirstChild("ball2")
        local p1, p2 = b1 and b1:FindFirstChildWhichIsA("BasePart"), b2 and b2:FindFirstChildWhichIsA("BasePart")
        if not model.Parent then RD.walls[model] = nil
        elseif p1 and p2 then
            local c, dt = (p1.Position + p2.Position) * 0.5, now - w.at
            if w.x and dt > 0.08 then
                local vx, vz = (c.X - w.x) / dt, (c.Z - w.z) / dt
                local sp = math.sqrt(vx * vx + vz * vz)
                if now - w.born < 0.4 or sp > 40 then vx, vz = 0, 0 end   -- a placement jump is not a velocity: a phantom wall once swept the arena and the bot fled into ice spikes
                w.vx, w.vz, w.x, w.z, w.at = vx, vz, c.X, c.Z, now
            elseif not w.x then w.x, w.z, w.at = c.X, c.Z, now end
            w.cx, w.cy, w.cz, w.halfLen = c.X, c.Y, c.Z, (p1.Position - p2.Position).Magnitude * 0.5 + 4
            local ax = Vector3.new(p1.Position.X - p2.Position.X, 0, p1.Position.Z - p2.Position.Z)
            if ax.Magnitude > 1 then ax = ax.Unit w.ax, w.az = ax.X, ax.Z end   -- the wall runs between its balls
        end
    end
    for part, r in pairs(RD.parts) do   -- bare projectiles: velocity from position; spent when faded and still, or still a while
        if not part.Parent then RD.parts[part] = nil
        else
            local p, dt = part.Position, now - r.at
            if dt > 0.08 then r.vx, r.vz, r.x, r.z, r.at = (p.X - r.x) / dt, (p.Z - r.z) / dt, p.X, p.Z, now end
            local speed = sqrt(r.vx * r.vx + r.vz * r.vz)
            if speed <= 2 then r.stillSince = r.stillSince or now else r.stillSince = nil end   -- the same threshold the emitter uses: a spear jittering between two thresholds flashed on and off forever
            local pn = lower(part.Name)
            local projectile = false
            for _, k in ipairs({ "strike", "shot", "rock", "ball", "spear", "shuriken", "missile", "crisscross", "spike", "bomb" }) do if pn:find(k, 1, true) then projectile = true break end end
            if (part.Transparency >= CFG.spentTransparency and speed <= 2 and now - r.spawn > 0.5)
                or ((not r.reg or projectile) and r.stillSince and now - r.stillSince > 1.0 and now - r.spawn > 0.8) then RD.parts[part] = nil end   -- a stopped projectile is gone, box and label
        end
    end
    for i = #RD.zones, 1, -1 do if now > RD.zones[i].untilAt + 0.5 then table.remove(RD.zones, i) end end
    for i = #RD.spawns, 1, -1 do
        local sp = RD.spawns[i]
        if now - sp.at > 10 or not sp.inst.Parent then RD.spawnSet[sp.inst] = nil table.remove(RD.spawns, i) end
    end
    if now - RD.lastEnemyScan > 0.5 then RD.lastEnemyScan = now pcall(scanEnemies, now) end
end

-- Every hazard as a box the field can test, into `out` (reused: no allocation per frame).
local function hazards(now, out)
    out = out or {}
    local n = 0
    for _, r in pairs(RD.models) do
        local anchor = (r.hb and r.hb.Parent) and r.hb or ((r.pc and r.pc.Parent) and r.pc or nil)
        local b = r.box
        if anchor then
            local size = anchor.Size
            local cyl = anchor:IsA("Part") and anchor.Shape == Enum.PartType.Cylinder
            if anchor == r.pc and not r.hb and not cyl then size = Vector3.new(size.X, max(size.Y, 10), size.Z) end
            if r.pad > 0 then size = cyl and Vector3.new(size.X, size.Y + r.pad * 2, size.Z + r.pad * 2) or Vector3.new(size.X + r.pad * 2, size.Y, size.Z + r.pad * 2) end
            if not b then b = { name = r.name, kind = "model", slim = r.slim } r.box = b end
            footprint(b, anchor.CFrame, size, false, cyl)
        end
        if b and (anchor or now <= r.untilAt) then   -- a Model destroyed when it fires keeps its last geometry while its window is open
            b.from, b.untilAt, b.exact = r.from, (anchor and r.long) and huge or r.untilAt, r.exact
            b.warn = not r.fired and now < r.from and r.pc ~= nil and r.pc.Parent ~= nil and r.pc.Transparency < 1   -- the warning stage: telegraph visible, not fired yet
            n = n + 1 out[n] = b
        end
    end
    for part, r in pairs(RD.parts) do
        local speed, size, pn, p = sqrt(r.vx * r.vx + r.vz * r.vz), part.Size, lower(part.Name), part.Position
        local half = max(size.X, size.Z) * 0.5
        if pn:find("bigspike", 1, true) then half = half + 8 end
        local b = r.box
        if not b then b = { name = part.Name, kind = "part", ground = false, warn = false } r.box = b end
        if pn:find("secondboss", 1, true) and pn:find("orb", 1, true) then   -- Bob's following orb: its body is lethal; the bubble round it is warm only
            local bb = r.bubble   -- (as a lethal 14-stud ball it walled the bot in with every spot red and no floor for a blink)
            if not bb then bb = { name = part.Name .. " bubble", kind = "part", ground = false, warn = false, weight = 0.45 } r.bubble = bb end
            footprint(bb, CFrame.new(p), Vector3.new(CFG.orbBubble * 2, 12, CFG.orbBubble * 2), true, false)
            bb.from, bb.untilAt = now, now + 0.5
            n = n + 1 out[n] = bb
        end
        if speed > 2 then
            b.moving, b.ox, b.oy, b.oz, b.dx, b.dz, b.speed, b.offset = true, p.X, p.Y, p.Z, r.vx / speed, r.vz / speed, speed, 0
            b.halfW, b.halfL, b.halfH, b.from, b.untilAt, b.pathStart = half, half, max(size.Y * 0.5, 6), now, now + CFG.projectileLookahead, now
            n = n + 1 out[n] = b
        else
            local still = r.stillSince and (now - r.stillSince) or 0
            local projectile = false
            for _, k in ipairs({ "strike", "shot", "rock", "ball", "spear", "shuriken", "missile", "crisscross", "spike", "bomb" }) do if pn:find(k, 1, true) then projectile = true break end end
            if (r.reg and not projectile) or still < 1.0 then   -- a stopped projectile is done a second later (the spear lay there "live" for its whole life); a catalogued field stays while it exists
                footprint(b, part.CFrame, Vector3.new(size.X, max(size.Y, 8), size.Z), false, false)
                b.from, b.untilAt = now, now + 1.0
                n = n + 1 out[n] = b
            end
        end
    end
    for _, w in pairs(RD.walls) do
        if w.cx then
            local speed = sqrt(w.vx * w.vx + w.vz * w.vz)
            local b = w.box
            if not b then b = { name = "wall", kind = "wall", ground = true, warn = false } w.box = b end
            if speed > 2 then
                b.moving, b.ox, b.oy, b.oz, b.dx, b.dz, b.speed, b.offset = true, w.cx, w.cy, w.cz, w.vx / speed, w.vz / speed, speed, 0
                b.halfW, b.halfL, b.halfH, b.from, b.untilAt, b.pathStart = w.halfLen or 30, 6, 10, now, now + 20, now
            else
                local c = Vector3.new(w.cx, w.cy, w.cz)
                local look = w.ax and Vector3.new(-w.az, 0, w.ax) or Vector3.new(0, 0, 1)   -- box X along the wall
                footprint(b, CFrame.lookAt(c, c + look), Vector3.new((w.halfLen or 30) * 2, 12, 12), false, false)
                b.from, b.untilAt = now, now + 1
            end
            n = n + 1 out[n] = b
        end
    end
    for _, z in ipairs(RD.zones) do n = n + 1 out[n] = z end
    for i = #out, n + 1, -1 do out[i] = nil end
    return out
end

local function start()
    pcall(function() RD.timeSync = require(ReplicatedStorage:FindFirstChild("timeSync")) end)
    RD.connections[#RD.connections + 1] = Workspace.DescendantAdded:Connect(function(d) task.defer(function() if d.Parent then pcall(consider, d, true) end end) end)
    local remotes = ReplicatedStorage:FindFirstChild("remotes")
    for _, r in ipairs(remotes and remotes:GetChildren() or {}) do
        if r:IsA("RemoteEvent") and r.Name:find("BossSpecficEvents", 1, true) then
            RD.connections[#RD.connections + 1] = r.OnClientEvent:Connect(function(name, a)
                local h = HANDLERS[name]
                if h then local ok, err = pcall(h, a) if not ok then logT("evt", 2, "Reader", tostring(name) .. ": " .. tostring(err)) end end
            end)
        end
    end
    pcall(function()   -- the game's own ground telegraphs: exact shape, exact impact time
        local BN = require(ReplicatedStorage:WaitForChild("Utility", 5):WaitForChild("BridgeNet2", 5))
        local id = BN.ReferenceIdentifier("action")
        RD.connections[#RD.connections + 1] = BN.ReferenceBridge("precastHitbox"):Connect(function(p)
            if type(p) ~= "table" then return end
            local fire = os.clock() + (p.delayUntilAttack or 0) - (Workspace:GetServerTimeNow() - (p.startTime or Workspace:GetServerTimeNow()))
            if p[id] == "Circle" and p.position then
                addZone({ name = "circle", cframe = CFrame.new(p.position), size = Vector3.new((p.radius or 5) * 2, 12, (p.radius or 5) * 2), round = true, from = fire, untilAt = fire + 0.45, telegraphed = true })
            elseif p.cframe and p.size then
                addZone({ name = "cube", cframe = p.cframe, size = Vector3.new(p.size.X, max(p.size.Y, 12), p.size.Z), from = fire, untilAt = fire + 0.45, telegraphed = true })
            end
        end)
    end)
    log("Reader", "listening")
end
local function stop()
    for _, c in ipairs(RD.connections) do pcall(c.Disconnect, c) end
    RD.connections = {}
end

S.RD, S.hazards, S.readerTick, S.readerStart, S.readerStop, S.gameClock = RD, hazards, readerTick, start, stop, gameClock
end
    end)()
    module(S)
end

-- ===== src/field.lua =====
do
    local module = (function()
-- field.lua - where is safe, when, and which nearby spot to be on.
-- dangerAt(x, y, z, t): 1 inside a box live at time t, fading over a shoulder outside it, 0 clear. Telegraphed boxes
-- count as live dodgeLead before they fire; moving bodies from the moment they are known. Melee mobs and the arena
-- leash are hazards too. decide(): scores a ring of spots; each line is sampled at the moments it would be crossed,
-- danger already on you discounted only until the ground under you fires (grace). Blink reflex first.
return function(S)
local CFG, RT, RD, Workspace = S.CFG, S.RT, S.RD, S.Workspace
local hazards, raycastParams, floorY, logT = S.hazards, S.raycastParams, S.floorY, S.logT
local sqrt, abs, max, min, cos, sin, pi, huge = math.sqrt, math.abs, math.max, math.min, math.cos, math.sin, math.pi, math.huge

local DG = { target = nil, reason = "", dangerHere = 0, here0 = 0, grace = huge, now = 0, offsets = {}, outer = {}, cands = {}, boxes = {},
    reach = 2, halfHeight = 5, feet = 3, approach = nil, heading = nil, headingAt = -huge, evalStats = {} }
local BLINK_BOSSES = { ["midgardian champion"] = true, ["bob the frost giant"] = true }   -- the blink fires only where the attacks are mapped
local CLEAR_T = { 0, 0.25, 0.5, 0.75 }   -- clear now and for the time to walk on; the whole dwell left the fan with no destination ever, and no blink
local WALL_PENALTY = 8   -- against the clean-spot bonus of 10: a padded spot loses to any open clean spot, beats any hot one

-- The near rings (the reach, dodgeRings of them) are always scored; the outer rings (12 studs apart past the reach,
-- 24 spots each) only when nothing near is clean - added to the near ones, never in their place, so the near
-- spots and the small moves they allow are always there.
local function ring(list, r, rays, phase)
    for i = 0, rays - 1 do
        local a = phase + i / rays * 2 * pi
        list[#list + 1] = { x = cos(a) * r, z = sin(a) * r, dist = r }
    end
end
local function buildOffsets()
    table.clear(DG.offsets) table.clear(DG.outer)
    local rings, rays = max(CFG.dodgeRings, 1), max(CFG.dodgeRays, 6)
    for k = 1, rings do ring(DG.offsets, CFG.dodgeReach * k / rings, rays, (k % 2 == 0) and pi / rays or 0) end
    for k = 1, 4 do ring(DG.outer, CFG.dodgeReach + 12 * k, 24, (k % 2 == 0) and pi / 24 or 0) end
    DG.offsetsKey = CFG.dodgeReach .. "/" .. rings .. "/" .. rays
end

-- Signed depth of a point inside a flat box (negative outside: the distance), -huge at the wrong height.
local function depthOf(b, px, py, pz, hh)
    if abs(py - b.cy) > b.hy + hh then return -huge end
    local qx, qz = px - b.cx, pz - b.cz
    if b.r then return b.r - sqrt(qx * qx + qz * qz) end
    local oa, ob = abs(qx * b.ax + qz * b.az) - b.ha, abs(qx * b.bx + qz * b.bz) - b.hb
    if oa <= 0 and ob <= 0 then return -max(oa, ob) end
    return -sqrt(max(oa, 0) ^ 2 + max(ob, 0) ^ 2)
end
-- The same for a moving body where it is at time `at`: depth, signed distance ahead of the body, along and across overshoot.
local function movingDepth(b, px, pz, at)
    local along = b.offset + b.speed * max(at - b.pathStart, 0)
    local qx, qz = px - (b.ox + b.dx * along), pz - (b.oz + b.dz * along)
    local ahead = qx * b.dx + qz * b.dz
    local a, s = abs(ahead) - b.halfL, abs(-qx * b.dz + qz * b.dx) - b.halfW
    if a <= 0 and s <= 0 then return -max(a, s), ahead, a, s end
    return -sqrt(max(a, 0) ^ 2 + max(s, 0) ^ 2), ahead, a, s
end
local function grade(depth, reach, shoulder)
    local d = depth + reach
    if d >= 0 then return 1 end
    if -d < shoulder then return 1 + d / shoulder end
    return 0
end

-- reachO / shoulderO override the padding: the blink asks the bare question (body radius only), not the graded one.
local function dangerAt(px, py, pz, t, reachO, shoulderO)
    local reach, hh, shoulder, now, boxes = reachO or DG.reach, DG.halfHeight, shoulderO or CFG.dodgeShoulder, DG.now, DG.boxes
    local at, worst = now + t, 0
    for i = 1, #boxes do
        local b = boxes[i]
        if not b.far then
            local depth
            if b.moving then
                if at <= b.untilAt and (b.ground or abs(py - b.oy) <= b.halfH + hh) then
                    local d, ahead, _, s = movingDepth(b, px, pz, at)
                    depth = d
                    -- the rest of its lane, ahead of the body, is a place not to stand
                    if d + reach < 0 and ahead > b.halfL and s <= reach and ahead - b.halfL <= b.speed * min(max(b.untilAt - at, 0), CFG.laneHorizon) and worst < CFG.pathLaneDanger then worst = CFG.pathLaneDanger end   -- only as far as the body gets in laneHorizon s: Bob's slow wall painted the whole entrance
                end
            elseif at >= b.from - ((not b.exact and (b.telegraphed or b.from > now)) and (b.lead or CFG.dodgeLead) or 0) and at <= b.untilAt then   -- an exact window (measured hit instant) takes no lead: a beam is safe to cross until its hit; a big zone carries a longer lead
                depth = depthOf(b, px, py, pz, hh)
            end
            if depth then
                local d = b.slim and grade(depth, min(reach, b.slim), min(shoulder, CFG.slimShoulder)) or grade(depth, reach, shoulder)
                if b.weight then d = d * b.weight end
                if d > worst then worst = d if worst >= 1 then return 1 end end
            end
        end
    end
    local L = RD.leash   -- outside the arena leash is the attack that has no box: a hard edge, four studs in
    if L and L.enemy.root.Parent and sqrt((px - L.enemy.root.Position.X) ^ 2 + (pz - L.enemy.root.Position.Z) ^ 2) - L.radius > -4 then return 1 end
    for i = 1, #RD.enemies do   -- a melee mob's swing is the one hit; the band past it is a soft preference
        local e = RD.enemies[i]
        if e.melee and not e.isBoss then
            local tt = min(t, 0.6)
            local d, swing = sqrt((px - e.x - e.vx * tt) ^ 2 + (pz - e.z - e.vz * tt) ^ 2), e.extent + e.meleeDistance + 2
            local v = d <= swing + reach and 1 or grade(-(d - swing - CFG.meleeBuffer), reach, shoulder * 2) * 0.5
            if v > worst then worst = v if worst >= 1 then return 1 end end
        end
    end
    return worst
end

-- Seconds until the ground under the character fires: 0 if a box is live on it, huge if none covers it.
local function graceHere(px, py, pz)
    local now, grace, reach, hh = DG.now, huge, DG.reach, DG.halfHeight
    for i = 1, #DG.boxes do
        local b = DG.boxes[i]
        if not b.far and now <= b.untilAt then
            if b.moving then
                if b.ground or abs(py - b.oy) <= b.halfH + hh then
                    for k = 0, 10 do
                        local t = k * 0.1
                        if t >= grace then break end
                        local _, _, a, s = movingDepth(b, px, pz, now + t)
                        if a <= reach and s <= reach then grace = t break end
                    end
                end
            elseif depthOf(b, px, py, pz, hh) + reach >= 0 then grace = min(grace, max(b.from - now, 0)) end
        end
    end
    return grace
end

-- Boxes that cannot matter to any spot this frame are skipped by every sample.
local function cull(rx, rz, now)
    local R = CFG.dodgeReach + 48 + 10   -- the outer rings reach 48 past the reach
    for i = 1, #DG.boxes do
        local b, d = DG.boxes[i], nil
        if b.moving then   -- distance to the stretch of path still to come
            local a0, a1 = b.offset + b.speed * max(now - b.pathStart, 0), b.offset + b.speed * max(min(b.untilAt, now + 30) - b.pathStart, 0)
            local qx, qz = rx - b.ox, rz - b.oz
            local along = min(max(qx * b.dx + qz * b.dz, a0), a1)
            d = sqrt((qx - b.dx * along) ^ 2 + (qz - b.dz * along) ^ 2) - sqrt(b.halfL ^ 2 + b.halfW ^ 2)
        else d = sqrt((rx - b.cx) ^ 2 + (rz - b.cz) ^ 2) - (b.r or sqrt(b.ha ^ 2 + b.hb ^ 2)) end
        b.far = d > R
    end
end

-- A slab the body's size, carried above the legs (its bottom at the step height, so debris and steps the Humanoid
-- walks over do not count), swept from here to the floor point there: anything solid in the way is a wall.
-- `y` is the floor height at the destination; `from` the root position.
local function walkable(from, x, y, z, params)
    local lift = CFG.maxStepHeight + 1.5
    local a = Vector3.new(from.X, from.Y - DG.feet + lift, from.Z)
    local hit = Workspace:Blockcast(CFrame.new(a), Vector3.new(2.5, 3, 2.5), Vector3.new(x, y + lift, z) - a, params)
    return hit == nil, hit
end
local function clearFor(x, y, z)   -- outside every box by the body margin, for the whole dwell (moving bodies included)
    for _, tt in ipairs(CLEAR_T) do if dangerAt(x, y, z, tt, DG.reach, 0) >= 0.3 then return false end end
    return true
end

-- The blink's destination: the nearest clear floor at most blinkMax away, same height (raycast there), clear sweep,
-- headroom, never beside a mob, never while airborne. Rings of 4, 6, 8 studs, sixteen directions.
local function blinkTarget(root, hum, rx, ry, rz, awayFrom)
    local params, rp = raycastParams(DG.approach and DG.approach.model or nil), root.Position
    local rings = awayFrom and { 8, 6, 4 } or { 4, 6, 8 }   -- a head start wants the farthest ring; an escape the nearest clear one
    local standard = hum.HipHeight + root.Size.Y * 0.5   -- standing height: a hop from mid-stride left the character hovering
    local under = Workspace:Raycast(rp, Vector3.new(0, -(standard + 3), 0), params)
    if not under or under.Normal.Y < 0.7 or abs(rp.Y - under.Position.Y - standard) > 0.8 then return nil end
    local above, feetY = standard + 0.05, under.Position.Y
    for _, dist in ipairs(rings) do
        if dist > CFG.blinkMax + 0.01 then continue end
        local best, bestScore = nil, huge
        for i = 0, 15 do
            local a = i / 16 * 2 * pi
            local x, z = rx + cos(a) * dist, rz + sin(a) * dist
            local clear = clearFor(x, ry, z)
            if clear and awayFrom and (x - awayFrom.X) * (rx - awayFrom.X) + (z - awayFrom.Z) * (rz - awayFrom.Z) <= 0 then clear = false end   -- outward from the landing point only
            if clear then
                for _, e in ipairs(RD.enemies) do
                    if not e.isBoss and (x - e.x) ^ 2 + (z - e.z) ^ 2 < (CFG.mobStandoff - 8) ^ 2 then clear = false break end
                end
            end
            if clear then
                local hit = Workspace:Raycast(Vector3.new(x, ry + 2, z), Vector3.new(0, -(above + 6), 0), params)
                if hit and hit.Normal.Y > 0.7 and abs(hit.Position.Y - feetY) <= 1.5 then
                    local dest = Vector3.new(x, hit.Position.Y + above, z)
                    if walkable(rp, x, hit.Position.Y, z, params) and not Workspace:Raycast(dest, Vector3.new(0, 3.5, 0), params) then
                        local score = max(dangerAt(x, ry, z, 0.6), dangerAt(x, ry, z, 1.2))
                        if score < bestScore then best, bestScore = dest, score end
                    end
                end
            end
        end
        if best then return best end
    end
end

-- The reflex: a lethal box on the character that fires before a walk could clear it. In fights only (a target within
-- 70, a mapped boss or a mob), walk-first, blinkCooldown apart (one extra hop per 20 s for a box already on us),
-- blinkPerMinute at most. To the marker itself when it is 4..blinkMax away and clear, else the ring search.
local function blink(root, hum, rx, ry, rz, now, grace)
    local ap = DG.approach
    -- The slam head start: 44 studs in two seconds cannot be run from the centre, so the first frame of the slam
    -- reflex hops 8 studs outward while the ground is still clean. Once per slam.
    local rf = RT.reflex
    local slamStart = rf ~= nil and rf.name == "slam" and not rf.hopped and now - (rf.startedAt or now) <= 0.6   -- tried through the first 0.6 s, not one frame: a criss cross lane can block every ring for a moment
    if not CFG.blink or not ap or (grace > CFG.blinkWindow and not slamStart) then return false end
    -- Mapped boss fights only: against mobs the hops came in pairs three seconds apart and the anti-cheat kicked (run of 2026-09-03).
    if sqrt((ap.x - rx) ^ 2 + (ap.z - rz) ^ 2) > 70 or not (ap.isBoss and ap.model and BLINK_BOSSES[string.lower(ap.model.Name)]) then return false end
    local since = now - (RT.lastBlinkAt or -huge)
    local slowed = (RT.speedNow or 22) < 12 and hum.MoveDirection.Magnitude > 0.1   -- ice spikes: commanded to run, moving at a walk
    local early = since >= 4 and slowed and now - (RT.lastBlinkDouble or -huge) >= 20
    if since < CFG.blinkCooldown and not (slamStart and since >= 3) and not early then return false end   -- no second hop inside the cooldown: two hops three seconds apart is the kick pattern
    if early and since < CFG.blinkCooldown then RT.lastBlinkDouble = now end
    local tg = DG.target
    local legs = min(CFG.tweenEscape, max(RT.speedNow or CFG.tweenEscape, 6))   -- the speed the character actually has: slowed by ice spikes it cannot walk out
    if tg and not slamStart and sqrt((tg.X - rx) ^ 2 + (tg.Z - rz) ^ 2) / legs + 0.35 <= grace then return false end   -- the legs make it
    local recent = 0
    for i = #RT.blinkTimes, 1, -1 do if now - RT.blinkTimes[i] <= 60 then recent = recent + 1 else break end end
    if recent >= CFG.blinkPerMinute + (slamStart and 1 or 0) then return false end   -- the slam hop may be a fourth in the minute (it went missing at three)
    local dest
    if tg and not slamStart then
        local md = sqrt((tg.X - rx) ^ 2 + (tg.Z - rz) ^ 2)
        if md >= 4 and md <= CFG.blinkMax + 0.5 and clearFor(tg.X, ry, tg.Z) then dest = Vector3.new(tg.X, tg.Y + hum.HipHeight + root.Size.Y * 0.5, tg.Z) end
    end
    dest = dest or blinkTarget(root, hum, rx, ry, rz, slamStart and RT.reflex.from or nil)
    if not dest then return false end
    if slamStart then rf.hopped = true end
    RT.blinkTimes[#RT.blinkTimes + 1] = now
    if #RT.blinkTimes > 20 then table.remove(RT.blinkTimes, 1) end
    if since < CFG.blinkCooldown then RT.lastBlinkDouble = now end
    RT.lastBlinkAt, RT.blinks = now, RT.blinks + 1
    RT.lastBlink = { at = now, from = root.Position, to = dest, dist = sqrt((dest.X - rx) ^ 2 + (dest.Z - rz) ^ 2), grace = grace }
    root.CFrame = CFrame.new(dest) * (root.CFrame - root.CFrame.Position)   -- rotation, WalkSpeed untouched
    local v = root.AssemblyLinearVelocity
    root.AssemblyLinearVelocity = Vector3.new(v.X, -4, v.Z)   -- settle onto the floor at once
    DG.target, DG.reason = nil, ("blink %.0f studs"):format(RT.lastBlink.dist)
    logT("blink", 0.5, "Field", DG.reason)
    return true
end

-- Bob's wall between here and a spot: the walk there goes through it. A spot on the far side of a wall box (moving
-- or still) within the wall's span is never taken (Chris: it keeps running into the walls coming toward it - the
-- field saw a clean spot behind the wall and walked straight into it).
local function crossesWall(rx, rz, x, z)
    local boxes = DG.boxes
    for i = 1, #boxes do
        local b = boxes[i]
        if b.kind == "wall" then
            local nx, nz, cx, cz, half
            if b.moving then nx, nz, cx, cz, half = b.dx, b.dz, b.ox, b.oz, b.halfW + 3   -- it moves along its normal; halfW is its span
            elseif b.bx then nx, nz, cx, cz, half = b.bx, b.bz, b.cx, b.cz, (b.ha or 30) + 3 end   -- the footprint's A axis runs along the wall, B across it
            if nx then
                local sB, sC = (rx - cx) * nx + (rz - cz) * nz, (x - cx) * nx + (z - cz) * nz
                if sB * sC < 0 then
                    local t = sB / (sB - sC)
                    local px, pz = rx + (x - rx) * t, rz + (z - rz) * t
                    if abs((px - cx) * -nz + (pz - cz) * nx) <= half then return true end
                end
            end
        end
    end
    return false
end

local function decide(root, hum)
    local now = os.clock()
    DG.now, DG.reach, DG.halfHeight, DG.feet = now, root.Size.X * 0.5 + CFG.dodgeMargin, (hum.HipHeight + root.Size.Y) * 0.5 + 2.5, hum.HipHeight + root.Size.Y * 0.5
    hazards(now, DG.boxes)
    if DG.offsetsKey ~= CFG.dodgeReach .. "/" .. max(CFG.dodgeRings, 1) .. "/" .. max(CFG.dodgeRays, 6) then buildOffsets() end
    local rp = root.Position
    local rx, ry, rz, dwell, moveAt = rp.X, rp.Y, rp.Z, CFG.dodgeDwell, CFG.dodgeMoveAt
    DG.origin = rp   -- where the candidates were measured from (the drawing)
    cull(rx, rz, now)
    local here0 = dangerAt(rx, ry, rz, 0)
    DG.here0 = here0
    DG.dangerHere = max(here0, dangerAt(rx, ry, rz, dwell * 0.5), dangerAt(rx, ry, rz, dwell))
    RT.moveBoost = DG.dangerHere >= moveAt   -- the burst keys off what arrives within the dwell (the big spike needs 23 studs of sidestep)
    local speed = RT.moveBoost and CFG.tweenEscape or (RT.walkSpeed or CFG.tweenWalk)
    local grace = graceHere(rx, ry, rz)
    DG.grace = grace
    if blink(root, hum, rx, ry, rz, now, grace) then return end

    local hx, hz = 0, 0   -- keep the last heading (no left-right shuffle)
    if DG.heading and now - DG.headingAt < 1.0 then hx, hz = DG.heading.X, DG.heading.Z end
    local ap, ax, az, adist = DG.approach, 0, 0, 0
    if ap then
        ax, az = ap.x - rx, ap.z - rz
        adist = sqrt(ax * ax + az * az)
        if adist > 0.01 then ax, az = ax / adist, az / adist end
    end
    local profile = ap and ap.isBoss and S.bossProfile(ap.model and ap.model.Name) or nil
    local home
    if profile and profile.home then   -- Bob: his home point, band distance from him toward the crystals
        local cen = S.bobCrystalCentroid()
        local hl = cen and sqrt((cen.X - ap.x) ^ 2 + (cen.Z - ap.z) ^ 2) or 0
        if hl > 1 then home = { x = ap.x + (cen.X - ap.x) / hl * ap.standoff, z = ap.z + (cen.Z - ap.z) / hl * ap.standoff } end
    end

    -- Danger along the line to a spot (fresh: not already on us until the ground fires) and on arrival through the dwell.
    local function score(ox, oz, dist)
        local T, worst, total, n = dist / speed, 0, 0, 0
        local steps = max(2, min(14, math.ceil(dist / 2.0)))   -- a sample every 2 studs: 0.09 s at escape speed, finer than any hit window
        for k = 1, steps - 1 do
            local f = k / steps
            local d = dangerAt(rx + ox * f, ry, rz + oz * f, T * f)
            local fresh = max((T * f < grace) and (d - here0) or d, 0)
            total, n = total + fresh + min(d, here0) * CFG.dodgeInsideWeight, n + 1
            if fresh > worst then worst = fresh end
        end
        local endWorst = 0
        for extra = 0, dwell + 1e-6, CFG.dodgeDwellStep do   -- the ground on arrival, checked every 0.15 s through the dwell
            local d = dangerAt(rx + ox, ry, rz + oz, T + extra)
            total, n = total + d, n + 1
            if d > worst then worst = d end
            if d > endWorst then endWorst = d end
        end
        return worst, worst * 0.5 + (total / n) * 0.5, endWorst
    end
    -- Danger dominates; then distance, the kept heading, backing off when hot, the pull to the band, the arena, the leash, the strafe.
    local function costOf(ox, oz, dist, graded)
        local cost = graded * CFG.dodgeDangerWeight + dist * CFG.dodgeDistanceCost
        if (hx ~= 0 or hz ~= 0) and here0 < 1 then cost = cost + 0.025 * (1 - (ox * hx + oz * hz) / dist) end
        if ap and DG.dangerHere >= moveAt and adist > 1 then
            local back = ((ox * ax + oz * az) / dist + 1) * 0.5   -- 0 straight back, 1 toward
            cost = cost + CFG.dodgeOutwardWeight * (ap.isBoss and back or CFG.dodgeMobRetreat * sqrt(back))
        end
        if ap then
            local cx, cz = rx + ox, rz + oz
            local dd, band = sqrt((cx - ap.x) ^ 2 + (cz - ap.z) ^ 2), ap.standoff
            local near = adist < band + 30
            cost = cost + CFG.dodgeApproachWeight * (near and 1 or 0.6) * max(dd - (band + 3), (band - 3) - dd, 0)
            local lead = RD.orbLead
            if lead then cost = cost + CFG.orbPullWeight * sqrt((cx - lead.goal.X) ^ 2 + (cz - lead.goal.Z) ^ 2)   -- toward the crystal of the orb's colour
            elseif home then cost = cost + CFG.bobHomeWeight * sqrt((cx - home.x) ^ 2 + (cz - home.z) ^ 2) end
            if profile and profile.fan and now < RD.fanUntil + 1.0 then   -- the fan: the lanes are only far enough apart out at the fan radius; anything inside it costs (Chris: it drifts to the centre and dies)
                local inner = (CFG.fanRadius - 8) - dd
                if inner > 0 then cost = cost + CFG.fanInnerWeight * inner end
            end
            if profile and profile.arenaPull then   -- the centre is padded too (Chris): a spot closer than hubKeepOut to the Champion costs, fan or not
                local tooClose = CFG.hubKeepOut - dd
                if tooClose > 0 then cost = cost + CFG.hubKeepOutWeight * tooClose end
            end
            if profile and profile.arenaPull then   -- inside the arena, every time: past the band + 20 (fanRadius in the fan) costs, 25 further is out
                local far = dd - ((now < RD.fanUntil + 1.0) and CFG.fanRadius or (band + 20))
                if far > 0 then cost = cost + CFG.dodgeArenaWeight * far end
                if far > 25 then cost = cost + 2 end
            end
            local L = RD.leash   -- a respawn outside the leash is pulled back in, not out
            if L and L.enemy.root.Parent then
                local outL = sqrt((cx - L.enemy.root.Position.X) ^ 2 + (cz - L.enemy.root.Position.Z) ^ 2) - (L.radius - 8)
                if outL > 0 then cost = cost + 0.08 * outL end
            end
            if near and CFG.strafe and adist > 1 then cost = cost + CFG.dodgeStrafeWeight * abs((ox * ax + oz * az) / dist) end
        end
        return cost
    end

    local wallHere = false
    for i = 1, #DG.boxes do if DG.boxes[i].kind == "wall" then wallHere = true break end end
    local params, cands, st = raycastParams(nil), DG.cands, { total = 0, valid = 0, noFloor = 0, notWalkable = 0, lethalEnd = 0 }
    DG.evalStats = st
    table.clear(cands)
    local function evaluate(offsets)
        local batch = {}
        for _, off in ipairs(offsets) do
            local ox, oz, dist = off.x, off.z, off.dist
            local worst, graded, endWorst = score(ox, oz, dist)
            if wallHere and crossesWall(rx, rz, rx + ox, rz + oz) then worst, graded, endWorst = 1, 1, 1 end   -- through Bob's wall: never
            local cost = costOf(ox, oz, dist, graded)
            if endWorst >= 0.999 then cost = cost + 100 end   -- the marker never sits on a box about to fire
            local safe = worst < CFG.dodgeSafeWorst and endWorst < moveAt
            if safe then cost = cost - 10 + dist * CFG.dodgeSafeDistanceCost end   -- the nearest clean spot is the marker (a blink can reach it)
            if DG.dangerHere >= 0.5 and dist < 8 then cost = cost + 1 end   -- four studs on hot ground is dithering
            local c = { ox = ox, oz = oz, dist = dist, danger = worst, endDanger = endWorst, cost = cost, safe = safe }
            batch[#batch + 1] = c
            cands[#cands + 1] = c
        end
        table.sort(batch, function(a, b) return a.cost < b.cost end)
        st.total = st.total + #batch
        local best, checked = nil, 0
        for _, c in ipairs(batch) do
            if best and c.cost >= best.cost then break end
            checked = checked + 1
            if c.endDanger >= 0.999 then st.lethalEnd = st.lethalEnd + 1 end
            local x, z = rx + c.ox, rz + c.oz
            local y = floorY(x, ry, z, params)
            if y and y - (ry - DG.halfHeight) <= CFG.maxStepHeight + 3 + c.dist * 0.2 and y >= ry - CFG.maxDropHeight then   -- a far spot may sit up a ramp
                local clear, hit = walkable(rp, x, y, z, params)
                if clear then
                    c.x, c.y, c.z, c.valid = x, y, z, true
                    st.valid = st.valid + 1
                    local free, nearest, origin = 0, CFG.dodgeWallLook, Vector3.new(x, y + 2.5, z)   -- openness: an open spot beats a corner
                    for k = 0, 5 do
                        local hit = Workspace:Raycast(origin, Vector3.new(cos(k * pi / 3), 0, sin(k * pi / 3)) * CFG.dodgeWallLook, params)
                        local dd = hit and hit.Distance or CFG.dodgeWallLook
                        free = free + dd
                        if dd < nearest then nearest = dd end
                    end
                    c.open, c.wall = free / 6, nearest
                    c.cost = c.cost + CFG.dodgeWallWeight * max(0, CFG.dodgeWallLook * 0.75 - c.open)
                    -- A wall inside the padding: not forbidden, but a last resort behind every open spot that is not hot.
                    if nearest < CFG.wallPadding then c.padded = true c.cost = c.cost + WALL_PENALTY end
                    if not best or c.cost < best.cost then best = c end
                else st.notWalkable = st.notWalkable + 1 c.blocked, c.blocker, c.hitPos = true, hit.Instance, hit.Position end   -- a wall in the way: forbidden
            else st.noFloor = st.noFloor + 1 end
            if (checked >= 14 and best and best.danger < moveAt) or checked >= 60 then break end
        end
        return best
    end
    local best = evaluate(DG.offsets)
    if not best or best.danger >= moveAt then   -- nothing near is clean: the outer rings as well, the near ones kept
        local far = evaluate(DG.outer)
        if far and (not best or far.danger < best.danger) then best = far end
    end

    if DG.target and (RT.stalledFor or 0) > 0.6 then DG.target, DG.reason = nil, "stalled" end   -- blocked by something the sweep missed
    local target = DG.target
    if target then   -- keep the spot while its line stays clean and nothing beats it clearly; drop it when its line closes
        local tx, tz = target.X - rx, target.Z - rz
        local d = sqrt(tx * tx + tz * tz)
        if d < 1.2 then DG.target = nil
        else
            local worst, graded, endWorst = score(tx, tz, d)
            if endWorst >= 0.999 then DG.target, DG.reason = nil, "spot closed"
            elseif here0 >= moveAt then   -- escaping: kept until reached unless a clearly better spot exists (re-picking every frame stood still)
                if best and best.danger < worst - 0.25 then DG.target, DG.reason = nil, "better spot" else return end
            elseif worst >= moveAt then DG.target, DG.reason = nil, "line closed"
            elseif best and best.cost > costOf(tx, tz, d, graded) - CFG.dodgeHysteresis then return end
        end
    end
    if DG.dangerHere < moveAt then   -- here is safe: move only for a clearly better spot (or toward the orb's crystal while one is out)
        if not best or best.danger >= moveAt then DG.target, DG.reason = nil, "waiting for a gap" return end
        local lead = RD.orbLead
        local stay = not (lead and sqrt((rx - lead.goal.X) ^ 2 + (rz - lead.goal.Z) ^ 2) > 6)
        if stay and best.cost > costOf(0, 0, 0.001, 0) - CFG.dodgeHysteresis then DG.target, DG.reason = nil, "safe here" return end
    end
    if best then
        DG.target = Vector3.new(best.x, best.y, best.z)
        DG.chosen = { dist = best.dist, danger = best.danger, endDanger = best.endDanger, cost = best.cost }
        local v = Vector3.new(best.ox, 0, best.oz)
        if v.Magnitude > 0.5 then DG.heading, DG.headingAt = v.Unit, now end
        DG.reason = ("danger %.2f, %.0f studs"):format(best.danger, best.dist)
    elseif not DG.target then   -- nothing with a floor: away from the nearest enemy, blindly
        local nearest, nd = nil, huge
        for _, e in ipairs(RD.enemies) do
            local d2 = (rx - e.x) ^ 2 + (rz - e.z) ^ 2
            if d2 < nd then nearest, nd = e, d2 end
        end
        DG.target = rp + (nearest and Vector3.new(rx - nearest.x, 0, rz - nearest.z).Unit or Vector3.new(0, 0, 1)) * CFG.dodgeReach
        DG.reason = "blind"
        logT("blind", 1, "Field", "no candidate with a floor")
    end
end

S.DG, S.dangerAt, S.decide, S.walkable = DG, dangerAt, decide, walkable
end
    end)()
    module(S)
end

-- ===== src/brain.lua =====
do
    local module = (function()
-- brain.lua - the legs and the state machine.
-- Legs: every move is Humanoid:Move (a CFrame write is a kick); the escape burst is WalkSpeed tweenEscape for at most
-- boostMaxRun s then boostRest s at walking speed. Each frame, in order: lead Bob's orb, flee a reflex (slam, fan),
-- the field's spot when the ground here is hot or the next step is unsafe, fight the target from its standoff
-- (back off, strafe), travel to the next room.
return function(S)
local CFG, RT, RD, DG = S.CFG, S.RT, S.RD, S.DG
local decide, dangerAt, walkable, raycastParams, floorY, setState, logT = S.decide, S.dangerAt, S.walkable, S.raycastParams, S.floorY, S.setState, S.logT
local Workspace, LocalPlayer, PathfindingService, VIM = S.Workspace, S.LocalPlayer, S.PathfindingService, S.VirtualInputManager
local sqrt, abs, max, min, cos, sin, rad, huge = math.sqrt, math.abs, math.max, math.min, math.cos, math.sin, math.rad, math.huge

local MV = { driving = false, controlsOff = false, facedAt = -huge, counts = { arrive = 0, walked = 0, boost = 0 } }
local BR = { target = nil, waypoints = nil, index = 1, pathAt = -huge, strafeDir = 1, strafeFlipAt = -huge }
local function flat(a, b) local dx, dz = a.X - b.X, a.Z - b.Z return sqrt(dx * dx + dz * dz) end
local function walkSpeed() return RT.walkSpeed or CFG.tweenWalk end

-- ---------------------------------------------------------------- legs
local function setControls(enabled)
    if MV.controlsOff == (not enabled) then return end
    if pcall(function()
        local controls = require(LocalPlayer.PlayerScripts.PlayerModule):GetControls()
        if enabled then controls:Enable() else controls:Disable() end
    end) then MV.controlsOff = not enabled end
end
local function setBoost(hum, on)
    local now = os.clock()
    -- A WalkSpeed we did not write (the ice spikes slow) is the game's: fighting it back to 22 every frame is what
    -- the anti-cheat sees as speed under a slow. Hands off for two seconds after any foreign value.
    local ws = hum.WalkSpeed
    if MV.ourWalkSpeed and math.abs(ws - MV.ourWalkSpeed) > 0.01 and (not RT.walkSpeedBefore or math.abs(ws - RT.walkSpeedBefore) > 0.01) then
        MV.foreignUntil = now + 2.0
        MV.ourWalkSpeed = nil
        RT.walkSpeedBefore = nil   -- do not restore over the game's value either
    end
    if (MV.foreignUntil or 0) > now then on = false end
    if on and (MV.boostBlockedUntil or 0) > now then on = false end
    if on then
        if not RT.walkSpeedBefore then RT.walkSpeedBefore, MV.boostSince = hum.WalkSpeed, now MV.counts.boost = MV.counts.boost + 1 end
        if now - MV.boostSince > (RT.reflex and 2.4 or CFG.boostMaxRun) then MV.boostBlockedUntil = now + CFG.boostRest   -- a reflex (the slam) needs the whole 2 s at speed
        else
            if hum.WalkSpeed ~= CFG.tweenEscape then hum.WalkSpeed = CFG.tweenEscape end
            MV.ourWalkSpeed = CFG.tweenEscape
            return
        end
    end
    if RT.walkSpeedBefore then pcall(function() hum.WalkSpeed = RT.walkSpeedBefore end) MV.ourWalkSpeed = RT.walkSpeedBefore RT.walkSpeedBefore = nil end
end
-- Walk toward `target`. A speed above the Humanoid's own is a burst; below it walks proportionally slower. True within `arrive`.
local function driveTo(hum, root, target, speed, arrive)
    local pos = root.Position
    local dir = Vector3.new(target.X - pos.X, 0, target.Z - pos.Z)
    MV.driving = true
    setControls(false)
    local walk = RT.walkSpeedBefore or hum.WalkSpeed
    if not RT.walkSpeedBefore then RT.walkSpeed = walk end
    setBoost(hum, speed > walk + 0.5)
    if dir.Magnitude <= (arrive or 1) then
        MV.counts.arrive = MV.counts.arrive + 1
        hum:Move(Vector3.zero, false)
        MV.stallSince = nil
        return true
    end
    MV.counts.walked = MV.counts.walked + 1
    local aimed = os.clock() - MV.facedAt < 0.25   -- face where we go unless the brain aimed us this frame
    if hum.AutoRotate == aimed then hum.AutoRotate = not aimed end
    hum:Move(dir.Unit * math.clamp(speed / max(hum.WalkSpeed, 1), 0.15, 1), false)
    local now = os.clock()   -- standing against something is noted for the brain, never a jump
    if MV.lastPos and (pos - MV.lastPos).Magnitude < 0.05 then MV.stallSince = MV.stallSince or now RT.stalledFor = now - MV.stallSince
    else MV.stallSince, RT.stalledFor = nil, 0 end
    MV.lastPos = pos
    return false
end
local function face(root, hum, point)
    local p = root.Position
    local look = Vector3.new(point.X - p.X, 0, point.Z - p.Z)
    if look.Magnitude < 0.5 then return end
    MV.facedAt = os.clock()
    if hum.AutoRotate then hum.AutoRotate = false end
    root.CFrame = CFrame.lookAt(p, p + look.Unit)
end
local function release(hum, root)
    if MV.driving then MV.driving = false if hum then hum:Move(Vector3.zero, false) end end
    if hum then setBoost(hum, false) if not hum.AutoRotate then hum.AutoRotate = true end end
    MV.stallSince, MV.lastPos = nil, nil
    setControls(true)
end

-- ---------------------------------------------------------------- standing
S.abilityReach = function()
    -- The cast reach is the measured range itself: the geyser is placed on the target up to the cap. With +3 the
    -- reach sat one stud past the standing distance and a strafing bot was out of reach half the time.
    if CFG.autoStandoff and RD.abilityRange then return max(CFG.abilityRadius, min(RD.abilityRange, CFG.autoStandoffMax) + 12) end   -- the geyser has an area: targets a dozen studs past the placement still take it
    return CFG.abilityRadius
end
-- The measured range less the margin: as far from the target as the ability still reaches. The least ranged slot
-- counts, rangeMargin inside a known cap, one past a reach that is only a lower bound; capped at autoStandoffMax.
local function rangeStandoff()
    if not (CFG.autoStandoff and RD.abilitySlots) then return nil end
    local best
    for _, s in pairs(RD.abilitySlots) do
        local v = s.cap and (s.cap - CFG.rangeMargin) or (s.reach and (s.reach + 5))   -- a reach is a lower bound: stand five past it and find out (damage landed at 66-72 with a remembered 57)
        if v and (not best or v < best) then best = v end
    end
    return best and min(best, CFG.autoStandoffMax) or nil
end
local function standoffFor(e)
    local ranged = rangeStandoff()
    -- Never inside weapon reach (melee mobs further than ranged ones), and as far as the ability still reaches.
    if not e.isBoss then return max(e.extent + (e.melee and CFG.mobStandoff or CFG.rangedStandoff), ranged or 0) end
    if S.bossProfile(e.model.Name).fan and os.clock() < RD.fanUntil + 1.0 then return CFG.fanRadius end   -- between the lanes, from the edge
    return max(CFG.bossStandoff, ranged or 0)
end
-- This room's mobs first, by the priority setting (melee first, ranged first, or simply the nearest); with none
-- within 150, the nearest enemy anywhere - the boss, or the next room's mobs - and the walk there is the travel.
local RANK = { melee = function(e) return e.melee and 0 or 1 end, ranged = function(e) return e.melee and 1 or 0 end, nearest = function() return 0 end }
local function pickTarget(rp)
    local rank = RANK[CFG.targetPriority] or RANK.nearest
    local best, bestR, bestD, far, farD = nil, huge, huge, nil, huge
    for _, e in ipairs(RD.enemies) do
        if e.humanoid.Health > 0 and e.model.Parent then
            local d = flat(rp, e.root.Position)
            if not e.isBoss and d < 150 then
                local r = rank(e)
                if r < bestR or (r == bestR and d < bestD) then best, bestR, bestD = e, r, d end
            elseif d < farD then far, farD = e, d end
        end
    end
    return best or far
end
-- Where to aim: the target, pulled to the centre of the mobs the AoE covers with it, so one cast hits the group;
-- only if every one of them stays inside the AoE round the shifted point.
local function aimPoint(e)
    local ep, r = e.root.Position, RD.aoe
    if not r or e.isBoss then return ep end
    local sx, sz, n = 0, 0, 0
    for _, o in ipairs(RD.enemies) do
        if not o.isBoss and o.humanoid.Health > 0 and flat(ep, o.root.Position) <= r then sx, sz, n = sx + o.x, sz + o.z, n + 1 end
    end
    if n <= 1 then return ep end
    local c = Vector3.new(sx / n, ep.Y, sz / n)
    for _, o in ipairs(RD.enemies) do
        if not o.isBoss and o.humanoid.Health > 0 and flat(ep, o.root.Position) <= r and flat(c, o.root.Position) > r then return ep end
    end
    return c
end

-- ---------------------------------------------------------------- travel
local function computePath(from, to)
    local path = PathfindingService:CreatePath({ AgentRadius = 2.5, AgentHeight = 5, AgentCanJump = true, WaypointSpacing = 4 })
    if pcall(path.ComputeAsync, path, from, to) and path.Status == Enum.PathStatus.Success then
        local wps = {}
        for _, w in ipairs(path:GetWaypoints()) do wps[#wps + 1] = w.Position end
        if #wps >= 2 then return wps end
    end
    local wps, n = {}, max(1, min(24, math.floor(flat(from, to) / 8)))   -- straight, in steps, when the navmesh has no answer
    for i = 1, n do wps[i] = from:Lerp(to, i / n) end
    return wps
end
local function lineClear(rp, to, exclude)
    return walkable(rp, to.X, rp.Y - DG.feet, to.Z, raycastParams(exclude))   -- the field's body-height sweep, at this floor
end
-- Is the next stretch of a walk safe for the moments it is crossed? Refused only for what would hurt during the crossing.
local function stepSafe(rp, to, speed)
    local dx, dz = to.X - rp.X, to.Z - rp.Z
    local len = sqrt(dx * dx + dz * dz)
    if len < 0.1 then return true end
    local step = min(len, 6)
    local ux, uz, T = dx / len * step, dz / len * step, step / max(speed, 4)
    return max(dangerAt(rp.X + ux * 0.5, rp.Y, rp.Z + uz * 0.5, T * 0.5), dangerAt(rp.X + ux, rp.Y, rp.Z + uz, T), dangerAt(rp.X + ux, rp.Y, rp.Z + uz, T + 0.3)) < CFG.stepBlockAt
end
-- The best scored candidate that had a floor and no wall in the way, or nil.
local function bestCandidate()
    local best
    for _, c in ipairs(DG.cands or {}) do if c.valid and not c.blocked and (not best or c.cost < best.cost) then best = c end end
    return best and Vector3.new(best.x, best.y, best.z) or nil
end
-- Standing still is allowed only on ground that stays clean. With the ground here going hot and nothing else to
-- do, the spot, else the best candidate, else away from the nearest enemy - never a stop (three deaths were the
-- character standing for the last half second: reflex given up, walk blocked, "in range" with no strafe point).
local function holdOrMove(hum, root, label)
    if (DG.dangerHere or 0) < CFG.dodgeMoveAt and (DG.grace or huge) >= 1.0 then release(hum, root) setState(label) return end   -- a box on us firing within a second counts as hot
    local dest = DG.target or bestCandidate()
    if not dest then
        local rp, nearest, nd = root.Position, nil, huge
        for _, e in ipairs(RD.enemies) do local d = flat(rp, e.root.Position) if d < nd then nearest, nd = e, d end end
        dest = rp + (nearest and Vector3.new(rp.X - nearest.x, 0, rp.Z - nearest.z).Unit or Vector3.new(0, 0, 1)) * 14
    end
    driveTo(hum, root, dest, CFG.tweenEscape, 1.0)
    setState(label .. "; moving off hot ground")
end
local function blocked(hum, root, label)   -- the next stretch is cut by an attack: the spot instead, never standing on ground about to go hot
    if DG.target then driveTo(hum, root, DG.target, CFG.tweenEscape, 1.0) setState(label .. " blocked; via spot") return false end
    holdOrMove(hum, root, label .. " blocked")
    return false
end
-- Straight when the line is clear; otherwise a path replanned rarely (every 4 s or a 20-stud move of the target),
-- resumed past the waypoints already behind. No progress for 2.5 s skips a waypoint.
local function travel(hum, root, to, speed, label, exclude)
    local rp, now = root.Position, os.clock()
    if flat(rp, to) < 70 and lineClear(rp, to, exclude) then
        BR.waypoints = nil
        if not stepSafe(rp, to, speed) then return blocked(hum, root, label) end
        driveTo(hum, root, to, speed, 1.5)
        setState(label .. " straight")
        return
    end
    if not BR.waypoints or flat(BR.pathTo, to) > 20 or now - BR.pathAt > 4 or BR.index > #BR.waypoints then
        BR.waypoints, BR.pathAt, BR.pathTo, BR.index = computePath(rp, to), now, to, 1
        for i, w in ipairs(BR.waypoints) do
            if (w.X - rp.X) * (to.X - rp.X) + (w.Z - rp.Z) * (to.Z - rp.Z) > 0 and flat(rp, w) > 2.5 then BR.index = i break end
        end
    end
    local wp = BR.waypoints[BR.index]
    while wp and flat(rp, wp) < 3 and BR.index < #BR.waypoints do BR.index = BR.index + 1 wp = BR.waypoints[BR.index] end
    if not wp then return end
    if not BR.progressAt or flat(rp, BR.progressPos) > 1.5 then BR.progressAt, BR.progressPos = now, rp end
    if now - BR.progressAt > 2.5 then
        BR.progressAt = now
        if BR.index < #BR.waypoints then BR.index = BR.index + 1 else BR.waypoints = nil end
        logT("stall", 2, "Brain", "no progress; skipping a waypoint")
        return
    end
    if not stepSafe(rp, wp, speed) then return blocked(hum, root, label) end
    driveTo(hum, root, wp, speed, 1.5)
    setState(("%s %d/%d"):format(label, BR.index, #BR.waypoints))
end

-- ---------------------------------------------------------------- fighting
local function pressKey(key)
    pcall(VIM.SendKeyEvent, VIM, true, key, false, game)
    task.delay(0.05, function() pcall(VIM.SendKeyEvent, VIM, false, key, false, game) end)
end
-- Any spell off cooldown? (the Tools carry their own cooldown value)
local function abilityReady()
    for _, c in ipairs({ LocalPlayer.Backpack, LocalPlayer.Character }) do
        if c then
            for _, t in ipairs(c:GetChildren()) do
                if t:IsA("Tool") and t:FindFirstChild("abilitySlot") then
                    local cd = t:FindFirstChild("cooldown")
                    if not cd or cd.Value <= 0.1 then return true end
                end
            end
        end
    end
    return false
end
-- Has this mob noticed us: coming our way, or already close.
local function aggroed(e, rp)
    local dx, dz = rp.X - e.x, rp.Z - e.z
    local d = sqrt(dx * dx + dz * dz)
    if d < 45 then return true end
    return d > 0.1 and (e.vx * dx + e.vz * dz) / d > 3
end
local function fight(hum, root, e, now)
    local ep = aimPoint(e)
    BR.aim = ep
    local d = flat(root.Position, ep)
    face(root, hum, ep)
    -- In range: cast. With castSafe on, not while the ground here is hot or about to be (the cast animation roots the character).
    if d <= S.abilityReach() and (not CFG.castSafe or (DG.dangerHere < CFG.dodgeMoveAt and DG.grace > CFG.castSafeGrace)) then
        RT.castQueue = RT.castQueue or {}
        local function cast(key, slot, last)
            if now - RT[last] < CFG.abilityInterval then return end
            RT[last] = now
            pressKey(key)
            RT.castQueue[#RT.castQueue + 1] = { slot = slot, at = now, pos = root.Position, targetPos = ep }   -- the reader measures the range
            while #RT.castQueue > 4 do table.remove(RT.castQueue, 1) end
        end
        if CFG.autoQ then cast(Enum.KeyCode.Q, "q", "lastQ") end
        if CFG.autoE then cast(Enum.KeyCode.E, "e", "lastE") end
    end
    if CFG.autoAttack and d <= CFG.attackRange + e.extent and now - RT.lastClick >= CFG.clickInterval then
        RT.lastClick = now
        local tool = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Tool")
        if tool then pcall(tool.Activate, tool) end
    end
end
-- A few studs along the tangent round the target, pulled toward the band; flipped when the way is dangerous or blocked or every 4 s.
local function strafePoint(root, e, standoff, now)
    local rp, ep = root.Position, e.root.Position
    local rx, rz = rp.X - ep.X, rp.Z - ep.Z
    local d = sqrt(rx * rx + rz * rz)
    if d < 0.5 then return nil end
    local ux, uz = rx / d, rz / d
    local stepLen, clampR = (e.melee and standoff - d > 2) and 2 or 6, e.melee and 8 or 4
    local radial = max(min(standoff - d, clampR), -clampR)
    local px, pz = rp.X - uz * BR.strafeDir * stepLen + ux * radial, rp.Z + ux * BR.strafeDir * stepLen + uz * radial
    local y = floorY(px, rp.Y, pz, raycastParams(e.model))
    local bad = not y or abs(y - rp.Y) > CFG.maxStepHeight + 3 or dangerAt(px, rp.Y, pz, stepLen / walkSpeed()) >= CFG.dodgeMoveAt
    if bad or now - BR.strafeFlipAt > 4 then
        BR.strafeDir, BR.strafeFlipAt = -BR.strafeDir, now
        if bad then return nil end
    end
    return Vector3.new(px, y, pz)
end
-- Rotate the flat unit vector u by deg and return the point dist studs along it.
local function turned(rp, u, deg, dist)
    local r = rad(deg)
    return rp + Vector3.new(u.X * cos(r) - u.Z * sin(r), 0, u.X * sin(r) + u.Z * cos(r)) * dist
end

-- ---------------------------------------------------------------- tick
local function brainTick(now)
    local char, hum, root = S.character()
    if not hum or not root or hum.Health <= 0 then setState("no character") BR.waypoints = nil return end
    local rp = root.Position
    do local v = root.AssemblyLinearVelocity RT.speedNow = math.sqrt(v.X * v.X + v.Z * v.Z) end   -- measured, for the blink's walk test
    local stuns = Workspace:FindFirstChild("stunParts")
    if stuns and stuns:FindFirstChild(LocalPlayer.Name) then   -- stunned by the game: moving now is what the anti-cheat kicks for
        release(hum, root)
        setState("stunned")
        return
    end
    local target = pickTarget(rp)
    BR.target, BR.aim = target, nil
    DG.approach = target and { x = target.root.Position.X, z = target.root.Position.Z, standoff = standoffFor(target), model = target.model, isBoss = target.isBoss } or nil
    if now - (DG.lastDecision or -huge) >= CFG.dodgeInterval then   -- 60 Hz is plenty; at 240 fps a per-frame field ate the frame
        DG.lastDecision = now
        local ok, err = pcall(decide, root, hum)
        if not ok then logT("decide", 2, "Field", tostring(err)) end
    end

    -- Bob's orbs (Chris: as long as it goes the right colour's way it can keep backing up). The nearest orb sets a
    -- pull point for the field - just behind the crystal of its colour, on the far side from the orb - and while
    -- an orb is out the field's spot leads every frame, so the dodging itself trends toward the crystal. The
    -- orb's bubble keeps the bot off it. Within orbHandoff of the crystal the orb is done and the pull is gone.
    RD.orbLead = nil
    if target and target.isBoss and S.bossProfile(target.model.Name).orbs then
        local orb, orbD = nil, 160
        for part in pairs(RD.parts) do
            local n = string.lower(part.Name)
            if part.Parent and n:find("secondboss", 1, true) and n:find("orb", 1, true) and flat(rp, part.Position) < orbD then orb, orbD = part, flat(rp, part.Position) end
        end
        local colour = orb and string.lower(orb.Name):match("secondboss(%a+)orb")
        local crystal = colour and S.bobCrystal(colour)
        if crystal and flat(orb.Position, crystal) > CFG.orbHandoff then
            local away = Vector3.new(crystal.X - orb.Position.X, 0, crystal.Z - orb.Position.Z)
            if away.Magnitude > 0.5 then
                local goal = Vector3.new(crystal.X, rp.Y, crystal.Z) + away.Unit * CFG.orbLeadBehind
                RD.orbLead = { colour = colour, goal = goal, orbD = orbD }
            end
        end
    end
    -- A reflex: an instadeath with a known centre (the slam, the fan). Straight out at escape speed until clear of its radius.
    local rf = RT.reflex
    if rf then
        local away = Vector3.new(rp.X - rf.from.X, 0, rp.Z - rf.from.Z)
        if now > rf.untilAt or away.Magnitude >= rf.radius then RT.reflex = nil
        else
            local u = away.Magnitude < 0.5 and Vector3.new(1, 0, 0) or away.Unit
            -- The most open safe heading, not the first: cornered against the rocks, the way out is along the wall
            -- or even back past the centre (145 and 180 degrees are tried), and a free run of 30 studs beats a
            -- radial 8. With nothing safe, the most open heading regardless (staying inside is the one certain death).
            local params = raycastParams(target and target.model)
            -- The heading that is out of the danger soonest. The slam box is a 67-stud cube, padded: 38 studs out
            -- through a face, 54 through a corner, and the old scoring (openness first) ran the diagonal and died at
            -- 40 of 44 twice. Each heading is measured to the box edge (or, for the fan, the radial distance left);
            -- a heading the rocks cut short of the exit is a last resort; ties go to the straighter run.
            local slamBox
            if rf.name == "slam" then for i = 1, #DG.boxes do local b = DG.boxes[i] if b.name == "firstbossjumpslam" and not b.moving and b.ax then slamBox = b break end end end
            local function exitAlong(dir)
                if slamBox then
                    for step = 0, 60, 2 do
                        if depthOf(slamBox, rp.X + dir.X * step, slamBox.cy, rp.Z + dir.Z * step, 0) < -(DG.reach + 2) then return step end
                    end
                    return 60
                end
                return (rf.radius - away.Magnitude) / max(dir.X * u.X + dir.Z * u.Z, 0.15)
            end
            local dest, bestScore, openDest, openScore = nil, -huge, nil, -huge
            for _, deg in ipairs({ 0, 35, -35, 70, -70, 110, -110, 145, -145, 180 }) do
                local dir = turned(Vector3.zero, u, deg, 1)
                local hit = Workspace:Raycast(rp + Vector3.new(0, 2, 0), dir * 60, params)
                local free = hit and hit.Distance or 60
                if free >= 8 then
                    local need = exitAlong(dir)
                    local score = -need - (free - 3 < need and 40 or 0) - abs(deg) / 400
                    local cand = rp + dir * min(14, free - 3)
                    if score > openScore then openScore, openDest = score, cand end
                    if score > bestScore and stepSafe(rp, cand, CFG.tweenEscape) then bestScore, dest = score, cand end
                end
            end
            dest = dest or openDest
            driveTo(hum, root, dest or (rp + u * 14), CFG.tweenEscape, 1.0)
            setState(("flee %s %.0f/%.0f"):format(rf.name, away.Magnitude, rf.radius))
            return
        end
    end
    -- The field's spot outranks everything while the ground here is hot now, or while the walk the brain wants is unsafe.
    if DG.target then
        local useSpot = DG.here0 >= CFG.dodgeMoveAt or RD.orbLead ~= nil   -- with an orb out the field's spot leads every frame
        if not useSpot then
            local walkTo = target and flat(rp, target.root.Position) > DG.approach.standoff + 3 and target.root.Position or nil
            useSpot = walkTo == nil or not stepSafe(rp, walkTo, walkSpeed())
        end
        if useSpot then
            driveTo(hum, root, DG.target, (RT.moveBoost or RD.orbLead) and CFG.tweenEscape or walkSpeed(), 1.2)
            setState(RD.orbLead and ("lead %s orb %.0f: "):format(RD.orbLead.colour, RD.orbLead.orbD) .. DG.reason or ("dodge " .. DG.reason))
            if target then fight(hum, root, target, now) end
            return
        end
    end
    if target then
        local standoff, ep = DG.approach.standoff, target.root.Position
        local d = flat(rp, ep)
        if d > standoff + 3 then   -- walking speed; escape speed only into the arena from far out (the mouth is where aimed attacks spawn on you)
            -- Mobs only (Chris): no ability off cooldown means no reason to wake a mob that has not noticed us. Wait
            -- outside its notice until one is ready; a mob already coming is fought as usual.
            if not target.isBoss and d < CFG.aggroHold + 10 and not abilityReady() and not aggroed(target, rp) then
                holdOrMove(hum, root, "waiting for cooldown")
                return
            end
            travel(hum, root, ep, (target.isBoss and d > standoff + 25) and CFG.tweenEscape or walkSpeed(), d > 150 and "to " .. target.model.Name or "approach", target.model)
            if d <= S.abilityReach() then fight(hum, root, target, now) end
            return
        end
        BR.waypoints = nil
        fight(hum, root, target, now)
        if d < standoff - (target.isBoss and 12 or 6) then   -- well inside the band: the most open way out, straight back first
            local away = Vector3.new(rp.X - ep.X, 0, rp.Z - ep.Z)
            if away.Magnitude > 0.5 then
                local u, params, dest, bestScore = away.Unit, raycastParams(target.model), nil, -huge
                for _, deg in ipairs({ 0, 40, -40, 80, -80, 120, -120 }) do
                    local dir = turned(Vector3.zero, u, deg, 1)
                    local hit = Workspace:Raycast(rp + Vector3.new(0, 2, 0), dir * 22, params)
                    local free = hit and hit.Distance or 22
                    if free >= 6 then
                        local cand = rp + dir * min(12, free - 3)
                        if stepSafe(rp, cand, CFG.tweenEscape) and free - abs(deg) / 40 > bestScore then bestScore, dest = free - abs(deg) / 40, cand end
                    end
                end
                if dest or DG.target then
                    driveTo(hum, root, dest or DG.target, CFG.tweenEscape, 1.0)
                    setState(dest and "back off" or "back off via spot")
                    return
                end
            end
        end
        if CFG.strafe then
            local p = strafePoint(root, target, standoff, now)
            if p then
                driveTo(hum, root, p, (target.melee and d < standoff - 2) and CFG.tweenEscape or walkSpeed() * CFG.strafeSpeedFraction, 1.0)
                setState("strafe")
                return
            end
        end
        holdOrMove(hum, root, "in range")
        return
    end
    release(hum, root)
    setState(S.runComplete() and "run complete" or "no enemy in sight")
end

S.MV, S.BR, S.brainTick, S.standoffFor, S.releaseMover, S.restoreWalkSpeed = MV, BR, brainTick, standoffFor, release, function(hum) if hum then setBoost(hum, false) end end
end
    end)()
    module(S)
end

-- ===== src/draw.lua =====
do
    local module = (function()
-- draw.lua - one translucent box per hazard coloured by stage (floor / soon / live), a faint outline at the size the
-- bot treats as unsafe, a strip along a moving body's remaining lane, and the spot marker. 10 Hz, 60 boxes, 130 studs.
return function(S)
local CFG, DG, RD, hazards, visualRoot = S.CFG, S.DG, S.RD, S.hazards, S.visualRoot
local DR = { parts = {}, nodes = {}, spots = {}, ring = {}, tags = {}, wallTags = {}, lastDraw = -math.huge, lastSweep = -math.huge, list = {} }

local function folder()
    if DR.folder and DR.folder.Parent then return DR.folder end
    DR.folder = Instance.new("Folder")
    DR.folder.Name = "Hazards"
    DR.folder.Parent = visualRoot()
    return DR.folder
end
local function part(parent, name, transparency)
    local p = Instance.new("Part")
    p.Name = name
    p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch, p.CastShadow = true, false, false, false, false
    p.Material, p.Transparency = Enum.Material.Neon, transparency
    p.Parent = parent
    return p
end
local function outline(p, thickness, colour)
    local e = Instance.new("SelectionBox")
    e.Name, e.LineThickness, e.SurfaceTransparency, e.Color3, e.Adornee, e.Parent = "edge", thickness, 1, colour, p, p
    return e
end
local function dot(list, i, colour, size, pos, transparency)
    local p = list[i]
    if not p or not p.Parent then p = part(folder(), "node", transparency) p.Shape = Enum.PartType.Ball list[i] = p end
    p.Size, p.Color, p.Transparency, p.CFrame = Vector3.new(size, size, size), colour, transparency, CFrame.new(pos)
end
local function trim(list, n) for i = #list, n + 1, -1 do list[i]:Destroy() list[i] = nil end end
-- A floating name. Parented to a part it labels that part; parented to the folder it labels its Adornee.
local function tag(parent, colour)
    local g = Instance.new("BillboardGui")
    g.Name, g.Size, g.AlwaysOnTop, g.MaxDistance, g.StudsOffsetWorldSpace, g.LightInfluence = "tag", UDim2.fromOffset(240, 22), true, 250, Vector3.new(0, 4, 0), 0
    local l = Instance.new("TextLabel")
    l.Name, l.Size, l.BackgroundTransparency, l.TextColor3, l.TextStrokeTransparency, l.TextScaled, l.Font = "text", UDim2.fromScale(1, 1), 1, colour, 0.2, true, Enum.Font.GothamBold
    l.Parent = g
    g.Parent = parent
    return g
end
local function newBox()
    local p = part(folder(), "box", CFG.hazardTransparency)
    outline(p, 0.05, CFG.colorFloor)
    tag(p, Color3.new(1, 1, 1))
    return p
end
-- The white warning outline: the box grown by the bot's margin and shoulder. Only while the attack is still coming
-- and its telegraph is visible; once it has fired or faded, the outline goes and only the live box stays.
local function sightFor(p, on)
    local sight = p:FindFirstChild("sight")
    if not on then if sight then sight:Destroy() end return nil end
    if not sight then sight = part(p, "sight", 1) outline(sight, 0.03, Color3.fromRGB(235, 235, 245)) end
    return sight
end

local function drawTick(now)
    if now - DR.lastDraw < 0.1 then return end
    DR.lastDraw = now
    if now - DR.lastSweep > 3 then   -- anything else under the visuals root is a leftover of an older build
        DR.lastSweep = now
        for _, f in ipairs(visualRoot():GetChildren()) do if f.Name ~= "Hazards" then f:Destroy() end end
    end
    local _, _, rt = S.character()
    local rp = rt and rt.Position
    local used, drawn = {}, 0
    if CFG.drawHazards then
        for _, b in ipairs(hazards(now, DR.list)) do   -- one Part per box object, so a box keeps its drawing (and its label) frame to frame
            local bx, bz = b.moving and b.ox or b.cx, b.moving and b.oz or b.cz
            if drawn < 60 and (not rp or (bx - rp.X) ^ 2 + (bz - rp.Z) ^ 2 < 130 * 130) then
                drawn = drawn + 1
                local p = DR.parts[b]
                if not p or not p.Parent then p = newBox() DR.parts[b] = p end
                used[b] = true
                local warn = b.warn
                if warn == nil then warn = not b.moving and now < b.from end   -- zones: coming until they fire
                local sight, sweep = sightFor(p, warn), p:FindFirstChild("sweep")
                local m = (b.slim and math.min(DG.reach, b.slim) or DG.reach) + (b.slim and CFG.slimShoulder or CFG.dodgeShoulder)
                if b.moving then   -- the body where it is now, and the lane it still has to cover as a faint strip
                    local along = b.offset + b.speed * math.max(now - b.pathStart, 0)
                    local cx, cz = b.ox + b.dx * along, b.oz + b.dz * along
                    local y = (b.ground and rp) and (rp.Y - 2.4) or (b.oy - b.halfH + 0.6)
                    p.Shape, p.Size = Enum.PartType.Block, Vector3.new(b.halfW * 2, 1, b.halfL * 2)
                    p.CFrame = CFrame.lookAt(Vector3.new(cx, y, cz), Vector3.new(cx + b.dx, y, cz + b.dz))
                    if sight then sight.Shape, sight.Size = p.Shape, Vector3.new(p.Size.X + m * 2, p.Size.Y, p.Size.Z + m * 2) end
                    if b.kind == "part" then if sweep then sweep:Destroy() end   -- only announced paths know where they are going
                    else
                        sweep = sweep or part(p, "sweep", 0.88)
                        local len = math.max(math.min(b.speed * math.max(b.untilAt - now, 0), 260), 1)
                        local c = Vector3.new(cx + b.dx * (b.halfL + len * 0.5), y, cz + b.dz * (b.halfL + len * 0.5))
                        sweep.Size, sweep.Color = Vector3.new(b.halfW * 2, 0.4, len), CFG.colorSoon
                        sweep.CFrame = CFrame.lookAt(c, c + Vector3.new(b.dx, 0, b.dz))
                    end
                else
                    if sweep then sweep:Destroy() end
                    if b.cyl then   -- a Part cylinder as the game shows it
                        p.Shape, p.Size, p.CFrame = Enum.PartType.Cylinder, Vector3.new(math.min(b.size.X, 1.5), b.size.Y, b.size.Z), b.cframe
                        if sight then sight.Shape, sight.Size = p.Shape, Vector3.new(p.Size.X, p.Size.Y + m * 2, p.Size.Z + m * 2) end
                    elseif b.round then
                        p.Shape, p.Size, p.CFrame = Enum.PartType.Cylinder, Vector3.new(0.6, b.size.X, b.size.X), b.cframe * CFrame.Angles(0, 0, math.rad(90))
                        if sight then sight.Shape, sight.Size = p.Shape, Vector3.new(p.Size.X, p.Size.Y + m * 2, p.Size.Z + m * 2) end
                    else
                        p.Shape, p.Size, p.CFrame = Enum.PartType.Block, Vector3.new(b.size.X, math.min(b.size.Y, 1.5), b.size.Z), b.cframe - Vector3.new(0, b.size.Y * 0.5 - 0.8, 0)
                        if sight then sight.Shape, sight.Size = p.Shape, Vector3.new(p.Size.X + m * 2, p.Size.Y, p.Size.Z + m * 2) end
                    end
                end
                if sight then sight.CFrame = p.CFrame end
                local c = now >= b.from and CFG.colorLive or (b.from - now <= CFG.dodgeLead and CFG.colorSoon or CFG.colorFloor)
                if p.Color ~= c then p.Color, p.edge.Color3 = c, c end
                p.Transparency = b.weight and 0.85 or CFG.hazardTransparency   -- soft bands stay faint
                local t = p.tag
                t.Enabled = CFG.labelHazards
                if t.Enabled then t.text.Text = ("%s  %s"):format(b.name or "?", now >= b.from and "live" or ("in %.1fs"):format(b.from - now)) end
            end
        end
    end
    for key, p in pairs(DR.parts) do if not used[key] then p:Destroy() DR.parts[key] = nil end end
    -- Routing: the travel waypoints (blue, the current one bright) and every spot the field scored (green clean,
    -- yellow warm, red hot; faint ones failed the floor or wall check).
    local n, BR = 0, S.BR
    if CFG.drawPath and BR.waypoints then
        for i, w in ipairs(BR.waypoints) do
            local cur = i == BR.index
            n = n + 1
            dot(DR.nodes, n, cur and Color3.fromRGB(120, 200, 255) or Color3.fromRGB(40, 90, 200), cur and 2.5 or 1.5, w + Vector3.new(0, 1.5, 0), cur and 0.1 or 0.4)
        end
    end
    trim(DR.nodes, n)
    n = 0
    if CFG.drawSpots and DG.origin then
        local o = DG.origin
        -- green clean and open; orange a wall inside the padding (last resort); yellow warm; red hot, or a wall in
        -- the way; faint: not checked or no floor.
        local moveAt = CFG.dodgeMoveAt
        for _, c in ipairs(DG.cands) do
            n = n + 1
            local colour, tr
            if c.blocked then colour, tr = CFG.colorLive, 0.6
            elseif c.danger >= 0.999 or c.endDanger >= 0.999 then colour, tr = CFG.colorLive, c.valid and 0.15 or 0.7   -- lethal: never
            elseif c.padded then colour, tr = Color3.fromRGB(255, 140, 0), 0.15
            elseif c.danger >= moveAt or c.endDanger >= moveAt then colour, tr = CFG.colorSoon, c.valid and 0.15 or 0.7   -- warm: costs, allowed
            elseif c.safe then colour, tr = CFG.colorFloor, c.valid and 0.15 or 0.7
            else colour, tr = CFG.colorSoon, c.valid and 0.15 or 0.7 end
            dot(DR.spots, n, colour, 1.2, c.valid and Vector3.new(c.x, c.y + 0.6, c.z) or Vector3.new(o.X + c.ox, o.Y - 2.4, o.Z + c.oz), tr)
        end
    end
    trim(DR.spots, n)
    -- What the bot took for walls: the blocking part named, at the point the sweep hit it (up to eight).
    n = 0
    if CFG.drawSpots then
        for _, c in ipairs(DG.cands) do
            if c.blocked and c.blocker and c.blocker.Parent and n < 8 then
                n = n + 1
                local g = DR.wallTags[n]
                if not g or not g.Parent then g = tag(folder(), Color3.fromRGB(255, 120, 120)) DR.wallTags[n] = g end
                g.Adornee, g.Enabled, g.text.Text = c.blocker, true, "wall: " .. c.blocker.Name
            end
        end
    end
    trim(DR.wallTags, n)
    -- Things that appeared near the character and nothing recognised, named in grey: read the name off the screen
    -- and add it to the catalogue.
    n = 0
    if CFG.labelUnknown and rp then
        for _, sp in ipairs(RD.spawns) do
            local inst = sp.inst
            local adornee = inst:IsA("BasePart") and inst or (inst.PrimaryPart or inst:FindFirstChildWhichIsA("BasePart"))
            if adornee and adornee.Parent and (adornee.Position - rp).Magnitude < 80 then
                n = n + 1
                local g = DR.tags[n]
                if not g or not g.Parent then g = tag(folder(), Color3.fromRGB(200, 200, 210)) DR.tags[n] = g end
                g.Adornee, g.Enabled = adornee, true
                local kids = ""
                if inst:IsA("Model") then
                    local names = {}
                    for _, ch in ipairs(inst:GetChildren()) do if ch:IsA("BasePart") and #names < 3 then names[#names + 1] = ch.Name end end
                    kids = #names > 0 and (" [" .. table.concat(names, ", ") .. "]") or ""
                end
                g.text.Text = ("? %s (%s)%s"):format(inst.Name, inst.ClassName, kids)
            end
        end
    end
    trim(DR.tags, n)
    -- The ability: its measured range as a ring of dots round the character, and its AoE where the next cast lands.
    n = 0
    local aim = S.BR.aim
    if CFG.drawAbility and rp then
        local range = RD.abilityRange and math.min(RD.abilityRange, CFG.autoStandoffMax) or CFG.abilityRadius
        for i = 0, 23 do
            local a = i / 24 * 2 * math.pi
            n = n + 1
            dot(DR.ring, n, CFG.colorAbility, 0.8, Vector3.new(rp.X + math.cos(a) * range, rp.Y - 2.4, rp.Z + math.sin(a) * range), 0.3)
        end
    end
    trim(DR.ring, n)
    local shape = RD.aoeShape
    if CFG.drawAbility and rp and aim and shape then
        if not DR.aoe or not DR.aoe.Parent then DR.aoe = part(folder(), "aoe", 0.7) DR.aoe.Color = CFG.colorAbility end
        local look = Vector3.new(aim.X - rp.X, 0, aim.Z - rp.Z)
        local at = Vector3.new(aim.X, aim.Y - 2.4, aim.Z)
        if shape.aoeRound then
            DR.aoe.Shape, DR.aoe.Size = Enum.PartType.Cylinder, Vector3.new(0.4, shape.aoeX, shape.aoeX)
            DR.aoe.CFrame = CFrame.new(at) * CFrame.Angles(0, 0, math.rad(90))
        else
            DR.aoe.Shape, DR.aoe.Size = Enum.PartType.Block, Vector3.new(shape.aoeX, 0.4, shape.aoeZ)
            DR.aoe.CFrame = look.Magnitude > 0.5 and CFrame.lookAt(at, at + look.Unit) or CFrame.new(at)
        end
    elseif DR.aoe then DR.aoe:Destroy() DR.aoe = nil end
    if CFG.drawTarget and DG.target then
        if not DR.target or not DR.target.Parent then
            DR.target = part(folder(), "target", 0.35)
            DR.target.Color, DR.target.Size = CFG.colorTarget, Vector3.new(2, 5, 2)
        end
        DR.target.CFrame = CFrame.new(DG.target + Vector3.new(0, 3, 0))
    elseif DR.target then DR.target:Destroy() DR.target = nil end
end
local function clearDrawing()
    if DR.folder then DR.folder:Destroy() end
    DR.folder, DR.target, DR.aoe = nil, nil, nil
    table.clear(DR.parts) table.clear(DR.nodes) table.clear(DR.spots) table.clear(DR.ring) table.clear(DR.tags) table.clear(DR.wallTags)
end

S.drawTick, S.clearDrawing = drawTick, clearDrawing
end
    end)()
    module(S)
end

-- ===== src/lobby.lua =====
do
    local module = (function()
-- lobby.lua - the loop outside the fight. The game's buttons are thin remote calls (decompiled 2026-09-02):
--   lobby: remotes.createLobby:InvokeServer(map, difficulty, minLevel, hardcore, private, waveDefence) -> true, then
--          remotes.startDungeon:FireServer(). Names are the lobby tiles' ("Northern Lands", "Nightmare").
--   level: remotes.changeStartValue presses START; workspace.dungeon.bossRoom.dungeonFinished turns true when the run
--          ends; the party owner may remotes.replayDungeon:FireServer(data); bonusBossPlayerVote answers the vote.
return function(S)
local CFG, RT, Workspace, ReplicatedStorage, LocalPlayer, log = S.CFG, S.RT, S.Workspace, S.ReplicatedStorage, S.LocalPlayer, S.log
local LB = { place = nil, placeAt = -math.huge, lastAttempt = -math.huge, lastStartPress = -math.huge, attempts = 0, busy = false, status = "off" }

local function placeManager()
    if LB.pm == nil then
        local ok, pm = pcall(function() return require(ReplicatedStorage.Utility.PlaceManager) end)
        LB.pm = ok and pm or false
    end
    return LB.pm or nil
end
local function placeName()   -- "Lobby" or "Level", the game's own answer, with the workspace values as a fallback
    local pm = placeManager()
    if pm and pm.GetPlaceName then
        local ok, name = pcall(pm.GetPlaceName)
        if ok and type(name) == "string" and name ~= "" then return name end
    end
    local dn = Workspace:FindFirstChild("dungeonName")
    return (dn and dn.Value ~= "") and "Level" or (Workspace:FindFirstChild("Lobby") and "Lobby") or "?"
end
local function setStatus(text)
    if LB.status ~= text then LB.status = text if S.refreshQueuePanel then S.refreshQueuePanel() end end
end
local function remote(name)
    local f = ReplicatedStorage:FindFirstChild("remotes")
    return f and f:FindFirstChild(name)
end
local function value(name, parent)
    local v = (parent or Workspace):FindFirstChild(name)
    return v and v:IsA("ValueBase") and v or nil
end
local function finished()
    local dungeon = Workspace:FindFirstChild("dungeon")
    local room = dungeon and dungeon:FindFirstChild("bossRoom")
    return room and value("dungeonFinished", room)
end

local function queueNow(reason)
    if LB.busy then return false end
    LB.busy, LB.lastAttempt, LB.attempts = true, os.clock(), LB.attempts + 1
    task.spawn(function()
        local ok, err = pcall(function()
            local create, start = remote("createLobby"), remote("startDungeon")
            if not create or not start then error("the lobby remotes are not present") end
            local gui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
            local info = gui and gui:FindFirstChild("queueGui") and gui.queueGui:FindFirstChild("lobbyInfo")
            if info and info.Visible then setStatus("party open; starting") start:FireServer() return end   -- a party we already made
            setStatus(("creating %s, %s"):format(tostring(CFG.autoQueueMap), tostring(CFG.autoQueueDifficulty)))
            local accepted = create:InvokeServer(CFG.autoQueueMap, CFG.autoQueueDifficulty, tonumber(CFG.autoQueueMinLevel) or 0, CFG.autoQueueHardcore == true, CFG.autoQueuePrivate == true, false)
            if accepted ~= true then setStatus("declined by the game") log("Queue", "declined: " .. tostring(accepted)) return end
            task.wait(CFG.autoQueueStartDelay)
            setStatus("starting")
            start:FireServer()
            log("Queue", ("queued %s on %s (%s)"):format(tostring(CFG.autoQueueMap), tostring(CFG.autoQueueDifficulty), tostring(reason or "auto")))
        end)
        if not ok then setStatus("failed; will retry") log("Queue", "queueing threw: " .. tostring(err)) end
        LB.busy = false
    end)
    return true
end
local function replayNow()   -- exactly what the game's own Replay button sends
    local replay = remote("replayDungeon")
    if not replay then return false end
    local data = {}
    for _, name in ipairs({ "dungeonName", "dungeonProgress", "dungeonStarted", "hardcore" }) do local v = value(name) if v then data[name] = v.Value end end
    if data.hardcore ~= nil then data.isHardcore = data.hardcore end
    local dungeon = Workspace:FindFirstChild("dungeon")
    for _, holder in ipairs({ dungeon, dungeon and dungeon:FindFirstChild("bossRoom") }) do
        for _, child in ipairs(holder:GetChildren()) do if child:IsA("ValueBase") then data[child.Name] = child.Value end end
    end
    if not data.dungeonName then return false end
    LB.replayFired = true
    replay:FireServer(data)
    setStatus("replay sent")
    return true
end
local function isOwner()
    local pm = placeManager()
    local ok, td = pcall(function() return pm.GetPlaceTeleportData() end)
    return not ok or type(td) ~= "table" or td.ownerId == nil or td.ownerId == LocalPlayer.UserId
end

local function lobbyTick(now)
    if not LB.place or LB.place == "?" or now - LB.placeAt > 5 then LB.place, LB.placeAt = placeName(), now end
    local level = LB.place == "Level"
    if CFG.autoFarmByPlace and LB.place ~= LB.farmAppliedFor and (level or LB.place == "Lobby") then   -- the master switch follows the place, once per change
        LB.farmAppliedFor = LB.place
        if RT.farmEnabled ~= level then RT.farmEnabled = level if S.setLoopButtonState then pcall(S.setLoopButtonState) end end
    end
    if level and CFG.autoStartDungeon then   -- a queued run waits at the spawn until START is pressed
        LB.levelArrivedAt = LB.levelArrivedAt or now
        local started = value("dungeonStarted")
        if started and not started.Value and now - LB.levelArrivedAt >= CFG.autoStartDelay and now - LB.lastStartPress >= 10 then
            LB.lastStartPress = now
            local r = remote("changeStartValue")
            if r then pcall(r.FireServer, r) log("Queue", "START pressed") end
        end
    end
    if level then   -- the bonus boss vote after the last boss: declined unless asked for (its arena is not mapped)
        local active = value("bonusBossVotingActive")
        if active and active.Value then
            LB.bonusVoteSeenAt = LB.bonusVoteSeenAt or now
            if not LB.bonusVoted and now - LB.bonusVoteSeenAt >= CFG.bonusVoteDelay then
                LB.bonusVoted = true
                local vote, answer = remote("bonusBossPlayerVote"), CFG.bonusBoss and "yes" or "no"
                if vote then task.spawn(function() pcall(vote.InvokeServer, vote, answer) end) log("Queue", "bonus boss vote: " .. answer) end
            end
        else LB.bonusVoteSeenAt, LB.bonusVoted = nil, false end
    end
    if not CFG.autoQueue then setStatus("off") return end
    if LB.place == "Lobby" then
        LB.arrivedAt = LB.arrivedAt or now
        if LB.busy then return end
        local waited = now - LB.arrivedAt
        if waited < CFG.autoQueueDelay then setStatus(("in the lobby; queueing in %.0fs"):format(CFG.autoQueueDelay - waited)) return end
        if now - LB.lastAttempt >= CFG.autoQueueRetry then queueNow("auto") end
    elseif level then
        LB.arrivedAt = nil
        if not CFG.autoQueueReplay or LB.replayFired then return end
        local v = finished()
        if not (v and v.Value) then setStatus("in a run") return end
        LB.finishedSeenAt = LB.finishedSeenAt or now
        if not isOwner() then setStatus("run finished; waiting for the game to return us") return end
        local left = CFG.autoQueueReplayDelay - (now - LB.finishedSeenAt)
        if left > 0 then setStatus(("run finished; replay in %.0fs"):format(left)) else replayNow() end
    else setStatus("waiting for the place to load") end
end

S.LB, S.lobbyTick, S.queueNow, S.replayNow = LB, lobbyTick, queueNow, replayNow
S.runComplete = function()   -- the boss room's flag, or the bonus boss vote on screen
    local v = finished()
    local active = value("bonusBossVotingActive")
    return (v ~= nil and v.Value == true) or (active ~= nil and active.Value == true)
end
S.QUEUE_MAPS = { "Desert Temple", "Winter Outpost", "Pirate Island", "King's Castle", "The Underworld", "Samurai Palace", "The Canals",
    "Steampunk Sewers", "Ghastly Harbor", "Orbital Outpost", "Volcanic Chambers", "Enchanted Forest", "Aquatic Temple", "Northern Lands", "Egg Island" }
S.QUEUE_DIFFICULTIES = { "Easy", "Medium", "Hard", "Insane", "Nightmare" }
end
    end)()
    module(S)
end

-- ===== src/main.lua =====
do
    local module = (function()
-- main.lua - the windows and the HUD on the kit, the destructor, the Heartbeat loop.
return function(S)
local K, T, CFG, RT, RD, UI = S.UIKit, S.UIKit.Theme, S.CFG, S.RT, S.RD, S.UI
local LocalPlayer, RunService, UserInputService, Workspace = S.LocalPlayer, S.RunService, S.UserInputService, S.Workspace
local sliderConnections, releaseMover, restoreWalkSpeed, readerStop, clearDrawing = S.sliderConnections, S.releaseMover, S.restoreWalkSpeed, S.readerStop, S.clearDrawing
local saveConfig, loadConfig, SCRIPT_VERSION = S.saveConfig, S.loadConfig, S.SCRIPT_VERSION
local widgets, windows, guiOpen = {}, {}, false
local function track(w) widgets[#widgets + 1] = w return w end
local function refreshAll() for _, w in ipairs(widgets) do if w.render then pcall(w.render) end end end
local function releaseCharacter() local _, hum, root = S.character() pcall(releaseMover, hum, root) return hum end

-- Streamer mode (Chris): nothing on screen says who is playing. Your nameplate's name, title and VIP tag and the HUD
-- name; the health numbers over your head and the HUD's health bar; the game's player list and Roblox's; other
-- players' nameplates; the chat. The character is drawn as a black block the size of the field's spot marker, its
-- model and armour invisible. Each part is its own toggle. Everything is put back as it was when the mode goes off.
local ST = { saved = {}, box = nil, coreChanged = {}, lastApply = -math.huge, on = false }
local Players, StarterGui, visualRoot = game:GetService("Players"), game:GetService("StarterGui"), S.visualRoot
local function stSet(inst, prop, value)
    if inst[prop] == value then return end
    local rec = ST.saved[inst]
    if not rec then rec = {} ST.saved[inst] = rec end
    if rec[prop] == nil then rec[prop] = inst[prop] end   -- the first value seen is the original
    inst[prop] = value
end
local function streamerPlate(plate, mine)
    if not plate then return end
    for _, d in ipairs(plate:GetDescendants()) do
        if d:IsA("GuiObject") then
            local n = string.lower(d.Name)
            local identity = n == "name" or n == "title" or n == "vip"
            if mine then
                if identity and CFG.streamerName then stSet(d, "Visible", false) end
                if n:find("health", 1, true) and CFG.streamerHealth then stSet(d, "Visible", false) end
            elseif identity then stSet(d, "Visible", false) end
        end
    end
end
local function streamerBody(char)
    local root = char:FindFirstChild("HumanoidRootPart")
    for _, d in ipairs(char:GetDescendants()) do
        if d:IsA("BasePart") then
            if d ~= root then stSet(d, "Transparency", 1) stSet(d, "CastShadow", false) end
        elseif d:IsA("Decal") or d:IsA("Texture") then stSet(d, "Transparency", 1)
        elseif d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam") then stSet(d, "Enabled", false) end
    end
    if root then
        local box = ST.box
        if not box or not box.Parent then
            box = Instance.new("Part")
            box.Name = "streamer"
            box.Anchored, box.CanCollide, box.CanQuery, box.CanTouch, box.CastShadow = true, false, false, false, false
            box.Material, box.Color, box.Size = Enum.Material.SmoothPlastic, Color3.new(0, 0, 0), Vector3.new(2, 5, 2)   -- the field's spot marker, black
            box.Parent = visualRoot()
            ST.box = box
        end
        box.CFrame = root.CFrame
    end
end
local function streamerHud()
    local pg = LocalPlayer:FindFirstChild("PlayerGui")
    if not pg then return end
    local status = pg:FindFirstChild("playerStatus")
    status = status and status:FindFirstChild("Frame")
    if status then
        local nm, hf = status:FindFirstChild("playerName"), status:FindFirstChild("healthFrame")
        if nm and CFG.streamerName then stSet(nm, "Visible", false) end
        if hf and CFG.streamerHealth then stSet(hf, "Visible", false) end
    end
    local lb = pg:FindFirstChild("playerStatsLeaderboard")
    if lb and CFG.streamerLeaderboard then stSet(lb, "Enabled", false) end
end
local function streamerCore(kind, hide)
    local ok, cur = pcall(StarterGui.GetCoreGuiEnabled, StarterGui, kind)
    if not ok then return end
    if hide then
        if cur then ST.coreChanged[kind] = true pcall(StarterGui.SetCoreGuiEnabled, StarterGui, kind, false) end
    elseif ST.coreChanged[kind] then ST.coreChanged[kind] = nil pcall(StarterGui.SetCoreGuiEnabled, StarterGui, kind, true) end
end
local function streamerRestore()
    for inst, rec in pairs(ST.saved) do for prop, v in pairs(rec) do pcall(function() inst[prop] = v end) end end
    table.clear(ST.saved)
    if ST.box then ST.box:Destroy() ST.box = nil end
    streamerCore(Enum.CoreGuiType.PlayerList, false)
    streamerCore(Enum.CoreGuiType.Chat, false)
    ST.on = false
end
local function streamerTick(now)
    if not CFG.streamer then if ST.on then streamerRestore() end return end
    ST.on = true
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if ST.box and ST.box.Parent and root then ST.box.CFrame = root.CFrame end   -- every frame: the block rides the character
    if now - ST.lastApply < 0.5 then return end
    ST.lastApply = now
    for inst in pairs(ST.saved) do if not inst.Parent then ST.saved[inst] = nil end end   -- a respawn leaves the old body behind
    if char then
        if CFG.streamerBody then streamerBody(char) elseif ST.box then ST.box:Destroy() ST.box = nil end
        streamerPlate(char:FindFirstChild("playerNameplate"), true)
    end
    streamerHud()
    if CFG.streamerOthers then
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p.Character then streamerPlate(p.Character:FindFirstChild("playerNameplate"), false) end
        end
    end
    streamerCore(Enum.CoreGuiType.PlayerList, CFG.streamerLeaderboard == true)
    streamerCore(Enum.CoreGuiType.Chat, CFG.streamerChat == true)
end
S.streamerRefresh = function() streamerRestore() ST.lastApply = -math.huge end   -- a toggle changed: back to normal, then applied afresh next tick

local function destructScript()
    if RT.destroyed then return end
    RT.destroyed = true
    pcall(saveConfig)
    for _, c in ipairs(sliderConnections) do pcall(c.Disconnect, c) end
    table.clear(sliderConnections)
    for _, k in ipairs({ "hudConnection", "mainConnection", "streamerConnection" }) do if RT[k] then RT[k]:Disconnect() RT[k] = nil end end
    pcall(streamerRestore)
    pcall(restoreWalkSpeed, releaseCharacter())
    pcall(readerStop)
    pcall(clearDrawing)
    for _, k in ipairs({ "visualRoot", "scriptGui" }) do if RT[k] then RT[k]:Destroy() RT[k] = nil end end
    if _G.DungeonAutofarmDestruct == destructScript then _G.DungeonAutofarmDestruct = nil end
    if _G.DungeonAutofarmVersion == SCRIPT_VERSION then _G.DungeonAutofarmVersion = nil end
    if _G.DungeonAutofarmState == S then _G.DungeonAutofarmState = nil end
end
_G.DungeonAutofarmDestruct = destructScript

local function cfgToggle(parent, text, key, order, explain, after)
    return track(K.toggle(parent, text, function() return CFG[key] end, function(v) CFG[key] = v if after then after(v) end end, order, explain))
end
local function cfgSlider(parent, text, unit, lo, hi, isFloat, key, order, explain)
    return track(K.slider(parent, text, unit, lo, hi, isFloat, function() return CFG[key] end, function(v) CFG[key] = v end, order, explain))
end

